/* Native TimeTracker Attendance — reference-based Clock view.
 * Scoped to the existing APSYNTRA board, no Monday shell/embedded app.
 */
.tt-native {
 --tt-orange:#e9572b;
 --tt-orange-dark:#d7471f;
 --tt-ink:#1b1c21;
 --tt-line:#dfe2e7;
 --tt-ground:#f5f6f8;
 --tt-card:#f8f9fc;
 color:var(--tt-ink);
 background:var(--tt-ground);
 border:1px solid #e3e5ea;
 border-radius:9px;
 overflow:hidden;
 min-width:0;
 font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
 font-size:13px;
}
.tt-native * { box-sizing:border-box; }
.tt-native button,.tt-native select,.tt-native textarea { font:inherit; }
.tt-native button { cursor:pointer; }
.tt-native button:disabled { cursor:not-allowed; }
.tt-native :is(button,select,textarea):focus-visible {
 outline:3px solid #f59b7c;
 outline-offset:3px;
}
.tt-app-header {
 display:flex;
 align-items:center;
 justify-content:space-between;
 flex-wrap:wrap;
 gap:16px;
 padding:14px 20px;
 background:#fafbfe;
 border-bottom:1px solid var(--tt-line);
}
.tt-app-brand { display:flex;align-items:center;gap:12px;min-width:0; }
.tt-brand-icon {
 width:34px;
 height:34px;
 flex:0 0 34px;
 background:var(--tt-orange);
 color:#fff;
 display:grid;
 place-items:center;
 border-radius:9px;
 box-shadow:0 3px 8px #cc6a4b24;
 font-size:22px;
 line-height:1;
}
.tt-app-brand h2 {
 margin:0 0 3px;
 font:700 17px/1.2 Georgia,"Times New Roman",serif;
 letter-spacing:-.01em;
}
.tt-app-brand p { margin:0;color:#686a70;font-size:11px; }
.tt-header-actions { display:flex;align-items:center;gap:10px; }
.tt-role-pill {
 border:1px solid #f6d0c1;
 background:#fff1ea;
 color:var(--tt-orange-dark);
 border-radius:20px;
 padding:7px 12px;
 font-size:11px;
 font-weight:650;
 white-space:nowrap;
}
.tt-notices {
 display:flex;
 justify-content:center;
 align-items:center;
 flex-wrap:wrap;
 gap:8px;
 margin:12px 20px;
 padding:9px 12px;
 border:1px solid var(--tt-line);
 border-radius:8px;
 background:#fafbfe;
 box-shadow:0 2px 5px #1d24300c;
 min-height:46px;
}
.tt-notice {
 padding:8px 11px;
 border-radius:5px;
 border:1px solid #dce1ea;
 background:#eff3f8;
 color:#59616d;
 font-size:11px;
 font-weight:550;
 white-space:normal;
}
.tt-notice-warning { border-color:#f5d1c4;background:#fff6f2;color:var(--tt-orange-dark); }
.tt-navigation {
 margin:0 20px;
 border-bottom:1px solid #dbdee4;
 min-width:0;
}
.tt-navigation-scroll {
 display:flex;
 gap:1px;
 overflow-x:auto;
 overflow-y:hidden;
 align-items:stretch;
 scrollbar-width:thin;
 overscroll-behavior-x:contain;
 scroll-snap-type:x proximity;
}
.tt-nav-tab {
 background:transparent;
 border:0;
 border-bottom:2px solid transparent;
 color:#5e6168;
 padding:14px 13px 12px;
 font-size:12px;
 font-weight:560;
 white-space:nowrap;
 scroll-snap-align:start;
 transition:color .12s ease,background-color .12s ease;
}
.tt-nav-tab:hover:not(:disabled) { color:var(--tt-orange-dark);background:#fff7f2; }
.tt-nav-tab.is-current {
 color:var(--tt-ink);
 border-bottom-color:var(--tt-orange);
 font-weight:720;
 background:#fff9f6;
}
.tt-nav-tab:disabled { opacity:.46;cursor:not-allowed; }
.tt-feedback {
 margin:12px 20px 0;
 padding:11px 14px;
 border-radius:7px;
 border:1px solid #d8e1ed;
 background:#f3f7fb;
}
.tt-feedback-error { background:#fff4f4;border-color:#f3c8cb;color:#9b2631; }
.tt-feedback-success { background:#f0faf4;border-color:#c9e9d4;color:#296c44; }
.tt-unavailable {
 min-height:310px;
 display:grid;
 place-items:center;
 text-align:center;
 padding:36px;
 color:#72747d;
}
.tt-clock-stage {
 display:flex;
 flex-direction:column;
 align-items:center;
 padding:48px 20px 54px;
 min-height:790px;
 background:#f6f6f8;
}
.tt-clock-hero { text-align:center; }
.tt-clock-hero h3 {
 margin:0;
 font:700 clamp(27px,3.2vw,37px)/1.2 Georgia,"Times New Roman",serif;
 letter-spacing:-.02em;
}
.tt-clock-hero p {
 margin:12px 0 0;
 color:#74747c;
 font-size:12px;
}
.tt-clock-face {
 display:flex;
 justify-content:center;
 align-items:baseline;
 gap:0;
 margin:34px 0 14px;
 font:700 clamp(58px,8.8vw,96px)/1 Georgia,"Times New Roman",serif;
 font-variant-numeric:tabular-nums;
 letter-spacing:-.04em;
 white-space:nowrap;
}
.tt-clock-colon {
 color:var(--tt-orange);
 padding:0 5px;
 transform:translateY(-2px);
}
.tt-clock-suffix {
 display:inline-flex;
 align-items:baseline;
 gap:5px;
 font:400 18px/1.2 Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
 letter-spacing:-.03em;
 padding-left:8px;
 color:#222329;
}
#tt-clock-seconds { font-variant-numeric:tabular-nums; }
.tt-session-summary {
 display:grid;
 grid-template-columns:repeat(3,minmax(0,1fr));
 width:min(100%,526px);
 margin:11px 0 27px;
 border:1px dashed #e1e1e6;
 border-radius:7px;
 overflow:hidden;
}
.tt-session-summary>div {
 display:grid;
 place-items:center;
 align-content:center;
 gap:7px;
 min-height:74px;
 padding:10px;
}
.tt-session-summary>div+div { border-left:1px dashed #e1e1e6; }
.tt-session-summary strong {
 font-size:18px;
 font-weight:750;
 font-variant-numeric:tabular-nums;
}
.tt-session-summary .tt-summary-status {
 font:italic 700 19px Georgia,"Times New Roman",serif;
}
.tt-session-summary span {
 font-size:9px;
 letter-spacing:.14em;
 text-transform:uppercase;
 color:#898990;
}
.tt-clock-card {
 width:min(100%,526px);
 padding:22px 21px 21px;
 background:var(--tt-card);
 border:1px solid #dce0e6;
 border-radius:9px;
 box-shadow:0 2px 3px #13192406;
}
.tt-clock-card-head {
 display:flex;
 align-items:center;
 justify-content:space-between;
 gap:12px;
 margin-bottom:21px;
}
.tt-clock-card h4 {
 margin:0;
 font:700 18px Georgia,"Times New Roman",serif;
}
.tt-idle-badge {
 padding:3px 9px;
 border:1px solid #d9dee7;
 background:#f3f5fa;
 border-radius:5px;
 font-size:10px;
 font-weight:750;
 color:#555a66;
 letter-spacing:.035em;
}
.tt-idle-badge.tt-badge-active {
 color:#16744b;
 background:#e8f6ed;
 border-color:#b6e0c4;
}
.tt-active-copy { margin:0 0 14px;color:#606872; }
.tt-clock-card form { display:grid;gap:15px; }
.tt-clock-card form>label {
 display:grid;
 gap:8px;
 color:#888b92;
 text-transform:uppercase;
 font-size:10px;
 font-weight:740;
 letter-spacing:.09em;
}
.tt-clock-card select,.tt-clock-card textarea {
 width:100%;
 min-height:46px;
 padding:11px 14px;
 background:#fafbfd;
 border:1px solid #d9dde5;
 border-radius:8px;
 color:#494c56;
 font-size:13px;
 font-weight:450;
 letter-spacing:normal;
 text-transform:none;
}
.tt-clock-card textarea { resize:vertical;max-height:180px; }
.tt-clock-card .tt-note-field[hidden] { display:none; }
.tt-quick-location {
 display:flex;
 align-items:center;
 flex-wrap:wrap;
 gap:7px;
 margin:-4px 0 3px;
}
.tt-quick-location>span {
 font-size:9px;
 letter-spacing:.1em;
 text-transform:uppercase;
 color:#92949d;
 margin-right:1px;
}
.tt-quick-location button {
 border:1px solid #e1e4e9;
 border-radius:19px;
 padding:5px 10px;
 background:#f0f2f6;
 color:#717782;
 font-size:10px;
}
.tt-quick-location button:hover,.tt-quick-location button.is-selected {
 color:var(--tt-orange-dark);
 background:#fff2ed;
 border-color:#ffc9b3;
}
.tt-start-button {
 display:block;
 width:100%;
 min-height:49px;
 border:0;
 border-radius:8px;
 background:var(--tt-orange);
 color:white;
 font-size:12px;
 font-weight:750;
 letter-spacing:.1em;
 text-transform:uppercase;
 transition:background-color .15s ease;
}
.tt-start-button:hover:not(:disabled) { background:var(--tt-orange-dark); }
.tt-start-button:disabled {
 background:#ebecef;
 color:#b4b5bb;
}
.tt-write-restriction {
 margin:0;
 font-size:11px;
 line-height:1.5;
 color:#94644e;
 text-align:center;
}
.tt-clock-hint {
 text-align:center;
 font-size:11px;
 color:#81848e;
 margin:0;
}
.tt-clock-footnote {
 max-width:540px;
 margin:24px 0 0;
 text-align:center;
 font-size:11px;
 line-height:1.55;
 color:#91939d;
}
.tt-secondary-content { padding:30px 22px 40px;min-height:540px; }
.tt-subview-head { margin-bottom:23px; }
.tt-subview-head h3 {
 margin:0 0 7px;
 font:700 29px/1.2 Georgia,"Times New Roman",serif;
}
.tt-subview-head p { margin:0;color:#767b85; }
.tt-content-panel {
 background:#fbfcff;
 border:1px solid #e0e4eb;
 border-radius:9px;
 padding:18px;
}
.tt-content-panel h4 {
 margin:0 0 18px;
 font:700 18px Georgia,"Times New Roman",serif;
}
.tt-panel-toolbar {
 display:flex;
 flex-wrap:wrap;
 gap:12px;
 align-items:center;
 justify-content:space-between;
 margin-bottom:14px;
}
.tt-panel-toolbar h4 { margin:0; }
.tt-panel-toolbar label { display:flex;gap:9px;align-items:center;color:#666b75; }
.tt-panel-toolbar select {
 background:#fff;
 color:#30333a;
 border:1px solid #dce1ea;
 border-radius:6px;
 padding:8px 12px;
}
.tt-content-panel .table-scroll {
 max-height:530px;
 overflow-x:auto;
 overflow-y:auto;
}
.tt-content-panel .board-table th {
 position:sticky;
 top:0;
 background:#f4f6fa;
 z-index:1;
}
.tt-muted {
 font-size:11px;
 line-height:1.6;
 color:#858a94;
 margin:16px 0 0;
}
@media(max-width:720px){
 .tt-app-header { padding:13px 14px; }
 .tt-notices { margin:10px 12px; }
 .tt-navigation { margin:0 10px; }
 .tt-nav-tab { padding:13px 11px; }
 .tt-clock-stage { padding:42px 13px 38px; min-height:650px; }
 .tt-clock-face { margin-top:27px; }
 .tt-clock-suffix { font-size:15px; }
 .tt-session-summary { margin-bottom:22px; }
 .tt-clock-card { padding:19px 16px; }
 .tt-secondary-content { padding:20px 12px; }
}
@media(max-width:420px){
 .tt-clock-face { font-size:54px; }
 .tt-clock-colon { padding:0 2px; }
 .tt-clock-suffix { font-size:12px;gap:3px;padding-left:5px; }
 .tt-clock-hero h3 { font-size:27px; }
 .tt-session-summary strong { font-size:16px; }
 .tt-session-summary .tt-summary-status { font-size:16px; }
 .tt-app-brand p { max-width:190px;line-height:1.3; }
}
@media(prefers-reduced-motion:reduce){
 .tt-nav-tab,.tt-start-button { transition:none; }
}


/* CP-TT-NATIVE-02: signed team Overview reference layout */

/* Native signed TimeTracker Log — grouped history, local table overflow only. */
.tt-log{padding:30px clamp(12px,2vw,26px) 40px;background:#f6f6f8;display:grid;gap:17px;min-width:0}
.tt-log[hidden],.tt-log [hidden]{display:none!important}
.tt-log-hero{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px}
.tt-log-hero h3{font:700 clamp(21px,2vw,27px)/1.2 Georgia,"Times New Roman",serif;margin:0 0 7px;color:#30343b}
.tt-log-hero p{font-size:12px;margin:0;color:#7c8190}
.tt-log-readonly{border:1px solid #d9e4dd;border-radius:20px;background:#eef6f0;color:#4e8062;font-size:11px;padding:7px 11px}
.tt-log-metrics{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:10px}
.tt-log-metric{background:#fff;border:1px solid #dfe2e8;border-radius:9px;padding:15px;min-width:0;display:grid;gap:8px}
.tt-log-metric span{font-size:11px;color:#777c87}
.tt-log-metric strong{font:700 23px/1.15 ui-monospace,SFMono-Regular,monospace;color:#30343b;font-variant-numeric:tabular-nums}
.tt-log-controls{display:flex;align-items:end;flex-wrap:wrap;gap:10px;background:#fff;border:1px solid #dfe2e8;border-radius:9px;padding:13px}
.tt-log-controls label{display:grid;gap:6px;font-size:11px;color:#757985;min-width:115px}
.tt-log-controls .tt-log-search{flex:1 1 210px}
.tt-log-controls input,.tt-log-controls select{height:37px;background:#fafbfc;border:1px solid #dce0e8;border-radius:6px;color:#3d434d;padding:0 10px;font:400 12px Inter,system-ui,sans-serif;width:100%;min-width:0}
.tt-log-controls input:focus-visible,.tt-log-controls select:focus-visible{outline:2px solid #eb754e;outline-offset:1px}
.tt-log-panel{background:#fff;border:1px solid #dfe2e8;border-radius:10px;min-width:0;padding:18px;display:grid;gap:16px}
.tt-log-panel-top{display:flex;gap:12px;justify-content:space-between;align-items:center;flex-wrap:wrap}
.tt-log-panel-top h4{font:700 16px Georgia,"Times New Roman",serif;margin:0 0 6px}
.tt-log-panel-top p{font-size:11px;color:#838894;margin:0}
.tt-log-panel-top button{white-space:nowrap}
.tt-log-day{min-width:0}
.tt-log-day h5{font:700 13px Georgia,"Times New Roman",serif;margin:0;padding:13px 3px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;color:#3b414b}
.tt-log-day h5 span{font:400 11px Inter,system-ui,sans-serif;color:#8c909a}
.tt-log-table-scroll{max-width:100%;overflow-x:auto;border:1px solid #e2e5ea;border-radius:7px}
.tt-log-table{min-width:1040px;width:100%;border-collapse:collapse}
.tt-log-table thead{background:#f7f8fa}
.tt-log-table th{font-size:10px;color:#858b97;white-space:nowrap;padding:12px 10px;text-align:left}
.tt-log-table td{font-size:11px;padding:14px 10px;vertical-align:middle;color:#484e58;white-space:nowrap;border-top:1px solid #f0f1f3}
.tt-log-table td strong{display:block;color:#363c46;font-size:12px}
.tt-log-table td small{display:block;color:#999ea7;font-size:10px;margin-top:4px}
.tt-log-table .tt-log-hours{font-variant-numeric:tabular-nums;font-weight:700}
.tt-log-badge{display:inline-flex;align-items:center;border-radius:14px;padding:5px 8px;font-size:10px;white-space:nowrap}
.tt-log-badge-active{background:#fff0e7;color:#c65324}
.tt-log-badge-done{background:#e9f5ee;color:#3d8559}
.tt-log-badge-unknown{background:#edf0f5;color:#657084}
.tt-log-location{font-size:11px}
.tt-log-detail{min-width:100px;max-width:180px}
.tt-log-detail summary{cursor:pointer;color:#c65324;font-weight:600;list-style-position:inside}
.tt-log-detail summary:focus-visible{outline:2px solid #c65324;outline-offset:3px}
.tt-log-detail-body{display:grid;gap:6px;max-width:180px;padding:10px 6px 4px;white-space:normal;line-height:1.5;color:#606774}
.tt-log-detail-body span{overflow-wrap:anywhere}
.tt-log-empty{padding:30px 12px;text-align:center;color:#858994;font-size:12px;border:1px dashed #e0e4e9;border-radius:7px}
.tt-log-footnote{font-size:11px;line-height:1.6;color:#8a909b;margin:0}
@media(max-width:1100px){.tt-log-metrics{grid-template-columns:repeat(4,minmax(0,1fr))}}
@media(max-width:540px){
 .tt-log{padding:18px 12px 28px}
 .tt-log-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}
 .tt-log-metric{padding:12px}
 .tt-log-metric strong{font-size:18px}
 .tt-log-panel{padding:12px}
 .tt-log-controls label{flex:1 1 140px}
 .tt-log-controls .tt-log-search{flex-basis:100%}
}

.tt-overview{padding:30px clamp(12px,2vw,26px) 40px;background:#f6f6f8;display:grid;gap:18px;min-width:0}
.tt-overview-hero{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:14px}
.tt-overview-hero h3{font:700 clamp(20px,2vw,27px)/1.2 Georgia,"Times New Roman",serif;margin:0 0 6px}
.tt-overview-hero p{color:#737680;margin:0;font-size:12px}
.tt-overview-live{display:flex;align-items:center;gap:13px;flex-wrap:wrap}
.tt-overview-live time{font:700 13px/1.3 ui-monospace,SFMono-Regular,monospace;color:#4b4e56}
.tt-overview-live>span{color:#9a9da8;font-size:10px}
.tt-overview-live button{padding:6px 12px}
.tt-overview-search{max-width:525px;display:grid;gap:6px}
.tt-overview-search label{font-size:11px;color:#777c86}
.tt-overview-search input{height:39px;width:100%;border:1px solid #dfe1e6;border-radius:7px;background:#fafbfe;padding:0 12px;font:inherit;color:inherit}
.tt-overview-metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));background:#fbfcff;border:1px solid #dfe2e9;border-radius:8px;overflow:hidden}
.tt-overview-metric{min-width:0;padding:16px 8px;display:grid;gap:7px;text-align:center;border-right:1px solid #e8eaf0}
.tt-overview-metric:nth-child(6){border-right:0}
.tt-overview-metric strong{font-size:23px;line-height:1;font-variant-numeric:tabular-nums}
.tt-overview-metric span{font-size:10px;color:#898d96}
.tt-on-time{grid-column:1/-1;display:flex;align-items:center;gap:10px;padding:10px 14px;border-top:1px solid #e8eaf0}
.tt-on-time>span{font-size:10px;color:#626a6f;white-space:nowrap}
.tt-on-time-bar{height:5px;border-radius:8px;background:#e3e6ec;flex:1;overflow:hidden}
.tt-on-time-bar i{display:block;background:#5a966d;height:100%;border-radius:8px}
.tt-on-time b{color:#63906c;font-size:11px;font-weight:700;white-space:nowrap}
.tt-overview-filters{display:flex;align-items:center;flex-wrap:wrap;gap:9px;padding:11px;background:#fbfcff;border:1px solid #e0e3e9;border-radius:7px}
.tt-overview-filters label{display:flex;align-items:center;gap:8px;color:#7c808b;font-size:10px}
.tt-overview-filters label:last-child{margin-left:auto}
.tt-overview-filters select{height:34px;max-width:210px;border:1px solid #dce0e8;border-radius:7px;background:#f9fafc;padding:0 9px;color:#4c505b;font:inherit;font-size:11px}
.tt-overview-locations{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}
.tt-overview-location{min-width:0;background:#fafbfe;border:1px solid #dfe3e9;border-radius:8px;padding:16px 11px;display:grid;gap:6px;position:relative}
.tt-overview-location:before{content:'';width:5px;height:5px;border-radius:100%;position:absolute;right:12px;top:12px;background:#a8b7d5}
.tt-overview-location:nth-child(3){border-top:2px solid #ef5c2c}
.tt-overview-location:nth-child(4){border-top:2px solid #783df2}
.tt-overview-location strong{font-size:23px;font-variant-numeric:tabular-nums}
.tt-overview-location span{font-size:10px;line-height:1.4;color:#696d77}
.tt-overview-location small{color:#a0a3ac;font-size:9px}
.tt-overview-panel{background:#fff;border:1px solid #dfe1e6;border-radius:9px;padding:16px;min-width:0}
.tt-overview-panel-heading{display:flex;align-items:center;flex-wrap:wrap;justify-content:space-between;gap:10px;margin-bottom:13px}
.tt-overview-panel-heading h4{font:700 15px/1.25 Georgia,"Times New Roman",serif;margin:0}
.tt-overview-panel-heading small,.tt-overview-panel-heading>b,.tt-overview-panel-heading>span{font-size:10px;color:#8b8e99}
.tt-location-track{height:24px;width:100%;background:#e9ecf2;display:flex;border-radius:5px;overflow:hidden}
.tt-location-segment{height:100%;display:grid;place-items:center;font-size:10px;font-weight:700;color:#fff;min-width:0}
.tt-location-color-0{background:#85a6e9}.tt-location-color-1{background:#9ec2b4}
.tt-location-color-2{background:#ea5b29}.tt-location-color-3{background:#793df3}
.tt-location-color-4{background:#55b3d6}
.tt-location-legend{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin-top:10px}
.tt-location-legend span{font-size:10px;color:#8b8e97}
.tt-location-legend i{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:4px}
.tt-overview-analytics{display:grid;grid-template-columns:1.05fr 1.05fr 1fr;gap:13px;min-width:0}
.tt-overview-analytics>.tt-overview-panel{min-height:280px}
.tt-arrival-bars{height:205px;display:flex;align-items:flex-end;gap:12px;border-bottom:1px solid #dce0e8;padding:12px 12px 18px}
.tt-arrival-bars>p{align-self:center;color:#90939e;margin:auto}
.tt-arrival-bar{flex:1 1 28px;min-width:14px;max-width:66px;height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:3px;position:relative}
.tt-arrival-bar b{font-size:10px;color:#e65a2b}
.tt-arrival-bar i{width:80%;background:#eb5d2c;border-radius:4px 4px 0 0;min-height:2px}
.tt-arrival-bar span{position:absolute;bottom:-18px;font-size:9px;color:#828793;white-space:nowrap}
.tt-pulse-grid{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:repeat(3,minmax(62px,1fr));border:1px solid #eef0f2;border-radius:5px;overflow:hidden}
.tt-pulse-grid>div{padding:13px;border-right:1px solid #eef0f2;border-bottom:1px solid #eef0f2;display:grid;align-content:center;gap:4px}
.tt-pulse-grid>div:nth-child(even){border-right:0}
.tt-pulse-grid>div:nth-last-child(-n+2){border-bottom:0}
.tt-pulse-grid strong{font-size:17px;color:#e85d2d}
.tt-pulse-grid small{font-size:10px;color:#747983}
.tt-late-list{display:grid;gap:9px}
.tt-late-list>div{display:flex;justify-content:space-between;gap:8px;border-bottom:1px solid #f0f1f4;padding-bottom:9px}
.tt-late-list b{font-size:11px}
.tt-late-list span{font-size:10px;color:#d65532;text-align:right}
.tt-late-list p{font-size:12px;color:#89909b}
.tt-overview-bottom{display:grid;grid-template-columns:1fr 1fr;gap:13px;min-width:0}
.tt-arrival-summary{font-size:11px;color:#8a8c96;margin-bottom:18px}
.tt-arrival-timeline{height:42px;background:linear-gradient(90deg,#f0f7f2,#fff3ec 49%,#faf0f2);border:1px solid #e7eaee;border-radius:6px;position:relative}
.tt-arrival-timeline i{position:absolute;top:50%;width:11px;height:11px;border-radius:50%;border:2px solid white;box-shadow:0 0 0 1px #d5d9dd;transform:translate(-50%,-50%);background:#71a77b}
.tt-arrival-timeline i.is-late{background:#e35f3d}
.tt-arrival-hours{display:flex;justify-content:space-between;color:#8c909a;font-size:10px;margin-top:11px}
.tt-department-row{margin:0 0 12px}
.tt-department-row>div:first-child{display:flex;justify-content:space-between;gap:9px;font-size:11px;margin-bottom:6px}
.tt-department-row span{color:#a1a4ad}
.tt-department-row>div:last-child{background:#e8eaf0;border-radius:3px;overflow:hidden;height:5px}
.tt-department-row i{display:block;height:100%;background:#e95b29}
.tt-overview-whereabouts{display:grid;gap:10px}
.tt-whereabouts-group{display:grid;gap:10px;margin-top:2px}
.tt-whereabouts-group h5{font:700 13px Georgia,"Times New Roman",serif;margin:0;color:#373943}
.tt-whereabouts-group h5 span{color:#8b8d98;font:400 11px Inter,sans-serif}
.tt-employee-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.tt-employee-card{background:#fafbfe;border:1px solid #dce1e8;border-radius:9px;padding:15px;display:grid;gap:9px;min-width:0}
.tt-employee-identity{display:flex;gap:11px;align-items:center;min-width:0}
.tt-employee-identity span{width:35px;height:35px;min-width:35px;border:2px solid #ed6537;border-radius:50%;display:grid;place-items:center;font:600 14px Georgia,"Times New Roman",serif;background:#f4f6f9;color:#666}
.tt-employee-identity strong{font:700 15px Georgia,"Times New Roman",serif;overflow-wrap:anywhere}
.tt-employee-card p{margin:0;color:#767985;font-size:11px}
.tt-employee-card p b{color:#3b3d45;font:600 11px ui-monospace,monospace}
.tt-employee-card>small{justify-self:end;background:#fff0ea;color:#e85a2a;border-radius:5px;padding:4px 7px;font-size:10px}
.tt-attendance-list .table-scroll{max-height:550px;overflow-x:auto;overflow-y:auto}
.tt-attendance-list .board-table{min-width:770px}
.tt-attendance-list .board-table th{position:sticky;top:0;background:#f5f6f9;z-index:1}
.tt-attendance-list .board-table td,.tt-attendance-list .board-table th{font-size:11px}
.tt-status-dot{display:inline-block;width:7px;height:7px;background:#7da59d;border-radius:50%;margin-right:6px}
.tt-status-dot.is-active{background:#e96233}
.tt-overview [hidden]{display:none!important}
@media(max-width:1100px){
 .tt-overview-analytics{grid-template-columns:repeat(2,minmax(0,1fr))}
 .tt-overview-analytics>.tt-overview-panel:last-child{grid-column:1/-1;min-height:auto}
 .tt-overview-locations{grid-template-columns:repeat(3,minmax(0,1fr))}
}
@media(max-width:720px){
 .tt-overview{padding:19px 12px 30px}
 .tt-overview-metrics{grid-template-columns:repeat(3,minmax(0,1fr))}
 .tt-overview-metric:nth-child(3){border-right:0}
 .tt-overview-metric:nth-child(-n+3){border-bottom:1px solid #e8eaf0}
 .tt-overview-analytics,.tt-overview-bottom{grid-template-columns:1fr}
 .tt-overview-analytics>.tt-overview-panel:last-child{grid-column:auto}
 .tt-employee-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
 .tt-overview-locations{grid-template-columns:repeat(2,minmax(0,1fr))}
 .tt-overview-filters label:last-child{margin-left:0}
 .tt-overview-filters select{max-width:170px}
}
@media(max-width:470px){
 .tt-overview-hero{align-items:flex-start}
 .tt-employee-grid{grid-template-columns:1fr}
 .tt-overview-metric strong{font-size:18px}
}

