/* CP-TT-CALENDAR-01 — month grid + historical analytics, scoped to signed TimeTracker. */
.tt-calendar{padding:30px clamp(14px,3vw,34px) 42px;background:#f8f7f7;color:#282b31;display:grid;gap:19px;min-width:0}
.tt-calendar[hidden],.tt-calendar [hidden]{display:none!important}
.tt-cal-header{display:flex;align-items:start;justify-content:space-between;gap:12px;flex-wrap:wrap}
.tt-cal-header h3{font:700 clamp(27px,3.2vw,34px)/1.2 Georgia,"Times New Roman",serif;margin:0 0 7px;color:#27282c}
.tt-cal-header p,.tt-cal-navigate p{margin:0;color:#7b7c83;font-size:12px}
.tt-cal-navigate{display:flex;gap:15px;align-items:end;justify-content:space-between;flex-wrap:wrap}
.tt-cal-navigate>div{display:grid;gap:8px}
.tt-cal-navigate small{font-size:10px;letter-spacing:.13em;color:#99979c;font-weight:700}
.tt-cal-navigate>div>div{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.tt-cal-navigate button{background:#fff;border:1px solid #e0e1e7;color:#5d646e;border-radius:5px;min-width:35px;min-height:32px;padding:5px 11px;font-size:15px;cursor:pointer}
.tt-cal-navigate button:disabled{opacity:.45;cursor:not-allowed}
.tt-cal-navigate strong{font:700 24px Georgia,"Times New Roman",serif;min-width:140px}
.tt-cal-navigate strong span{font:400 15px ui-monospace,monospace;color:#8e8c90}
.tt-cal-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));background:#fff;border:1px solid #e4e4e7;border-radius:9px;overflow:hidden}
.tt-cal-kpis>div{min-width:0;min-height:72px;display:grid;align-content:center;justify-items:center;gap:6px;border-right:1px dashed #e0e2e5}
.tt-cal-kpis>div:last-child{border:0}
.tt-cal-kpis strong{font:700 clamp(15px,2vw,21px) ui-monospace,monospace;color:#e3662f}
.tt-cal-kpis span{font-size:10px;letter-spacing:.09em;text-transform:uppercase;color:#94949c}
.tt-cal-metric-note{margin:-9px 0 0;font-size:10px;color:#95969f;line-height:1.5}
.tt-cal-section-title{display:flex;align-items:center;gap:15px;color:#96969e;font-weight:700;letter-spacing:.12em;font-size:11px}
.tt-cal-section-title:after{content:"";height:1px;background:#e1e2e6;flex:1;min-width:14px}
.tt-cal-section-title span{order:2;letter-spacing:0;font-size:10px;font-weight:400;white-space:nowrap}
.tt-cal-analytics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px;min-width:0}
.tt-cal-panel{background:#fff;border:1px solid #e0e2e6;border-radius:9px;padding:19px;min-width:0}
.tt-cal-panel h4{font:700 17px Georgia,"Times New Roman",serif;margin:0 0 9px}
.tt-cal-panel>p{font-size:11px;color:#92939b;margin:0 0 11px;line-height:1.6}
.tt-cal-trend{display:block;width:100%;height:auto;max-height:215px}
.tt-cal-trend-bar{fill:#e9692f}
.tt-cal-baseline{stroke:#e9e9ee;stroke-width:1}
.tt-cal-weekbars{display:grid;gap:11px;padding:12px 0 0}
.tt-cal-weekbar{display:grid;grid-template-columns:35px minmax(0,1fr) 35px;gap:10px;align-items:center}
.tt-cal-weekbar span{color:#777a86;font:600 11px ui-monospace,monospace}
.tt-cal-weekbar strong{color:#404652;font:700 11px ui-monospace,monospace;text-align:right}
.tt-cal-weekbar progress{display:block;width:100%;height:12px;accent-color:#65ad91}
.tt-cal-weekbar progress::-webkit-progress-bar{background:#f1f1f3;border-radius:4px}
.tt-cal-weekbar progress::-webkit-progress-value{background:#65ad91;border-radius:4px}
.tt-cal-month{overflow-x:auto;overflow-y:visible}
.tt-cal-weekdays,.tt-cal-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));min-width:690px;gap:6px}
.tt-cal-weekdays{margin-bottom:9px}
.tt-cal-weekdays span{text-align:center;font-size:11px;color:#95949c;font-weight:700;text-transform:uppercase}
.tt-cal-weekdays span:first-child,.tt-cal-weekdays span:last-child{color:#d69283}
.tt-cal-grid{grid-auto-rows:minmax(87px,auto)}
.tt-cal-day{position:relative;display:flex;flex-direction:column;align-items:flex-start;gap:5px;background:#fafbfe;color:#3f4550;border:1px solid #e2e5eb;border-radius:6px;padding:9px 8px;min-width:0;min-height:87px;text-align:left;cursor:pointer}
.tt-cal-day:hover{border-color:#e99d7d;background:#fff8f5}
.tt-cal-day:focus-visible{outline:3px solid #d9693e;outline-offset:2px}
.tt-cal-outside{background:#f7f7f8;border-color:transparent;pointer-events:none}
.tt-cal-day-number{font:700 12px ui-monospace,monospace}
.tt-cal-day small{font-size:10px;color:#98979d}
.tt-cal-count{position:absolute;top:8px;right:8px;border-radius:14px;background:#ea6c37;color:#fff;padding:3px 6px;font:700 10px ui-monospace,monospace}
.tt-cal-has-records{background:#fffaf4;border-color:#f2ca9b}
.tt-cal-high{background:#fff4e9;border-color:#e88a59}
.tt-cal-today{box-shadow:inset 0 0 0 2px #e36a45}
.tt-cal-selected-day{outline:2px solid #ce613b;outline-offset:1px}
.tt-cal-now{font-size:8px;background:#e96332;color:white;padding:3px 5px;border-radius:8px;line-height:1}
.tt-cal-holiday-label{background:#db7b13;color:#fff;border-radius:3px;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:9px;padding:4px 6px}
.tt-cal-holiday-regular .tt-cal-holiday-label{background:#bd383e}
.tt-cal-holiday-working .tt-cal-holiday-label{background:#737c94}
.tt-cal-heatmap-note{font-size:10px!important;color:#92949a;text-align:right;margin:13px 0 0!important}
.tt-cal-selected{background:#fff;border:1px solid #e0e2e6;border-radius:9px;padding:17px;display:grid;gap:12px}
.tt-cal-selected h4{font:700 18px Georgia,serif;margin:0}
.tt-cal-selected>p{color:#888d94;font-size:12px;margin:0}
.tt-cal-attendees{display:grid;gap:6px}
.tt-cal-attendee{display:flex;align-items:center;justify-content:space-between;gap:10px;border:1px solid #e9ebee;border-radius:6px;padding:11px 12px}
.tt-cal-attendee>div{display:grid;gap:5px;min-width:0}
.tt-cal-attendee strong{font-size:12px;color:#40424c;overflow-wrap:anywhere}
.tt-cal-attendee small{font-size:11px;color:#8b8c94;overflow-wrap:anywhere}
.tt-cal-attendee span{font:600 11px ui-monospace,monospace;color:#5e6470}
.tt-cal-legend{display:flex;justify-content:center;flex-wrap:wrap;gap:8px 19px;padding:9px;border:1px dashed #e2e3e6;background:#fff;border-radius:7px}
.tt-cal-legend span{font-size:10px;color:#797d88}
.tt-cal-legend span:nth-child(1){color:#bd383e}
.tt-cal-legend span:nth-child(2){color:#cb801a}
.tt-cal-legend span:nth-child(3){color:#737c94}
.tt-cal-holiday-list{display:grid;gap:10px}
.tt-cal-holiday-list>div{display:flex;gap:10px;align-items:center;border-bottom:1px solid #eeeff1;padding:5px 0 11px}
.tt-cal-holiday-list>div strong{font-size:12px;color:#343943;flex:1}
.tt-cal-holiday-list time{color:#8c919c;font:500 11px ui-monospace,monospace}
.tt-cal-holiday-type{font:700 9px ui-monospace,monospace;color:#fff;background:#da8124;padding:5px 7px;border-radius:4px}
.tt-cal-type-regular{background:#b9353e}
.tt-cal-type-working{background:#727c94}
.tt-cal-source{margin:0!important;font-size:10px!important;color:#9398a1}
.tt-cal-source a{color:#be602e}
@media(max-width:950px){.tt-cal-analytics{grid-template-columns:1fr}}
@media(max-width:600px){.tt-calendar{padding:17px 12px 30px;gap:15px}.tt-cal-panel{padding:12px}.tt-cal-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.tt-cal-kpis>div:nth-child(2){border-right:0}.tt-cal-kpis>div:nth-child(-n+2){border-bottom:1px dashed #e0e2e5}.tt-cal-navigate strong{font-size:21px}.tt-cal-attendee{align-items:flex-start;flex-direction:column}}


/* CP-TT-CALENDAR-UPCOMING */
.tt-cal-upcoming{display:flex;gap:15px;align-items:center;justify-content:space-between;flex-wrap:wrap;border:1px solid #f1cdbd;background:#fff5f0;border-radius:8px;padding:13px 16px}
.tt-cal-upcoming>div{display:grid;gap:5px}
.tt-cal-upcoming small{color:#9b795f;font-weight:700;letter-spacing:.1em;font-size:10px}
.tt-cal-upcoming strong{color:#41454c;font-size:13px}
.tt-cal-upcoming span{color:#8c8c96;font-size:11px}
.tt-cal-upcoming b{background:#e46b32;color:#fff;padding:8px 12px;border-radius:18px;font-size:11px}


/* CP-TT-OT-01 — reference-inspired native OT, with no fabricated decisions */
.tt-overtime{max-width:1024px;margin:0 auto;padding:38px clamp(14px,3vw,34px);display:grid;gap:20px;color:#2c2b2c}
.tt-ot-header{display:flex;align-items:start;justify-content:space-between;gap:15px}
.tt-ot-header h3{font:700 32px Georgia,serif;margin:0 0 7px;color:#27282a}
.tt-ot-header p{font-size:12px;color:#85848a;margin:0}
.tt-ot-header button{border:0;background:transparent;color:#8c9297}
.tt-ot-week{display:grid;gap:10px}
.tt-ot-week>small{letter-spacing:.15em;color:#96979b;font-size:10px;font-weight:700}
.tt-ot-week>div{display:flex;gap:9px;align-items:center;flex-wrap:wrap}
.tt-ot-week>div button{border:1px solid #e4e4e9;background:#fff;border-radius:5px;min-height:35px;padding:8px 12px;font-size:12px;color:#555b65}
.tt-ot-week>div strong{font:700 13px system-ui,sans-serif;color:#272b31}
.tt-ot-week>div .tt-ot-submit{margin-left:auto;background:#edaf9d;border-color:#edaf9d;color:#543a31;font-weight:700}
.tt-ot-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px dashed #e2e3e6;border-radius:7px;background:#fafafa}
.tt-ot-metrics>div{padding:20px 5px;display:grid;justify-items:center;gap:6px;border-right:1px dashed #e2e3e6}
.tt-ot-metrics>div:last-child{border:0}
.tt-ot-metrics strong{font:700 20px ui-monospace,monospace}
.tt-ot-metrics span{font-size:10px;letter-spacing:.1em;color:#8e9099}
.tt-ot-subline{text-align:center;color:#92959b;font-size:11px;margin:-10px 0 0}
.tt-ot-section-heading{display:flex;align-items:center;gap:12px;color:#8b8d94;font-size:11px;letter-spacing:.13em;font-weight:700}
.tt-ot-section-heading:after{content:"";background:#e0e0e5;height:1px;flex:1}
.tt-ot-section-heading span{order:2;font-size:10px;letter-spacing:0;font-weight:400}
.tt-ot-insights{display:grid;grid-template-columns:1fr 1fr;gap:15px}
.tt-ot-insights article{border:1px solid #e0e0e6;background:#fafbfe;border-radius:8px;min-height:170px;padding:17px;min-width:0}
.tt-ot-insights h4{font-size:10px;letter-spacing:.1em;color:#90939b;margin:0 0 15px}
.tt-ot-chart{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px;height:112px}
.tt-ot-chart>div{display:grid;gap:4px;justify-items:center}
.tt-ot-chart-track{height:88px}
.tt-ot-chart progress{width:100%;height:80px;writing-mode:vertical-lr;direction:rtl;accent-color:#e86430}
.tt-ot-chart small{font-size:9px;color:#9da0a8}
.tt-ot-requestor{display:grid;grid-template-columns:minmax(80px,1fr) 80px 18px;gap:10px;align-items:center;margin:10px 0}
.tt-ot-requestor b{font-size:11px;overflow-wrap:anywhere}
.tt-ot-requestor progress{accent-color:#e86430;width:100%;height:10px}
.tt-ot-requestor span{font-size:11px}
.tt-ot-list{padding:18px;background:#fafbfe;border:1px solid #e0e2e7;border-radius:8px;min-height:255px}
.tt-ot-tabs{display:flex;flex-wrap:wrap;gap:3px;margin-bottom:16px}
.tt-ot-tabs button{border:1px solid #e2e3e6;background:#f7f7f8;padding:11px 14px;color:#898b93;font-size:11px;font-weight:700}
.tt-ot-tabs button.is-active{border-color:#9298a9;background:#fff;color:#1d222a}
.tt-ot-tabs span{color:#e16734}
.tt-ot-search{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:14px}
.tt-ot-search label{font-size:11px;color:#848892}
.tt-ot-search input{min-width:180px;max-width:100%;flex:1;border:1px solid #e1e2e7;padding:10px;border-radius:5px;background:#fff}
.tt-ot-search button{background:transparent;border:0;color:#9a9da3;font-size:11px}
.tt-ot-row-head,.tt-ot-request>summary{display:grid;grid-template-columns:2fr 1fr 1fr 1fr 35px;align-items:center;gap:12px;min-width:620px;padding:11px;font-size:11px}
.tt-ot-row-head{font-size:10px;letter-spacing:.1em;color:#9396a0}
.tt-ot-request{border-top:1px solid #e2e3e6}
.tt-ot-request>summary{cursor:pointer;list-style:none;outline-offset:-2px}
.tt-ot-request>summary::-webkit-details-marker{display:none}
.tt-ot-request>summary:hover{background:#fff}
.tt-ot-request>summary>span:first-child{font-weight:700}
.tt-ot-pill{display:inline-flex;width:max-content;border-radius:12px;padding:5px 8px;font-size:10px}
.tt-ot-submitted{background:#fff0da;color:#b66a0a}
.tt-ot-approved{background:#e3f5ef;color:#188061}
.tt-ot-rejected{background:#fce9ed;color:#bf3b4b}
.tt-ot-detail{background:#fff;border-radius:5px;margin:2px 8px 10px;padding:12px;display:flex;flex-wrap:wrap;gap:12px}
.tt-ot-detail span,.tt-ot-detail p{font-size:11px;color:#68707c}
.tt-ot-detail p{flex-basis:100%;margin:0}
.tt-ot-empty{min-height:160px;display:grid;justify-items:center;align-content:center;gap:8px;color:#888d95}
.tt-ot-empty>span{font-size:25px}
.tt-ot-empty strong{font-size:12px}
.tt-ot-empty p{font-style:italic;font-size:11px}
