.tt-gps-map-canvas .tt-map-consent,.tt-gps-map-canvas .tt-map-empty{width:100%;height:100%}
@media(max-width:650px){.tt-log-street-map .tt-map-host{height:260px}
 .tt-map-consent{padding:14px}}

/* CP-TT-MAP-02 — visible recoverable map errors without masking the canvas. */
.tt-log-map-modes{display:flex;gap:5px;padding:7px;background:#f5f7f9;z-index:2}
.tt-log-map-modes button{font-size:11px;border:1px solid #d8dde6;border-radius:5px;
 padding:7px 12px;color:#536377;background:#fff;min-height:30px}
