.tt-map-message button:focus-visible,.tt-map-banner button:focus-visible,
.tt-log-map-modes button:focus-visible{outline:3px solid #ec925d;outline-offset:2px}
.tt-map-banner{position:absolute;bottom:28px;left:8px;right:8px;z-index:5;
 display:flex;justify-content:center;gap:8px;align-items:center;flex-wrap:wrap;
 font-size:11px;padding:7px;border:1px solid #cfdae4;border-radius:6px;
 background:#fffef1eb;color:#475366;pointer-events:auto}
.tt-map-host .tt-map-message{height:100%;width:100%}
.tt-map-host .tt-map-message span{max-width:350px}

/* CP-TT-LEAFLET-01: same-origin overlays; raster tiles only from OSM standard. */
.tt-map-host .leaflet-container{font:inherit;background:#edf2f5}
.tt-map-host .leaflet-control-attribution{font-size:10px;max-width:95%;white-space:normal}
.tt-map-host .leaflet-control-zoom a:focus-visible{outline:3px solid #2178b9;outline-offset:2px}
