 color:#7d86a0;font-size:19px;line-height:1;user-select:none;
 touch-action:manipulation
}
.board-card-actions>summary::-webkit-details-marker{display:none}
.board-card-actions>summary:hover,.board-card-actions[open]>summary{background:#f1f3ff;color:#545ede}
.board-card-actions>summary:focus-visible,.board-card-actions-list button:focus-visible{
