.board-card-actions-list{
 position:absolute;top:calc(100% + 5px);right:0;
 width:max-content;min-width:215px;max-width:min(290px,80vw);
 z-index:50;padding:6px;border:1px solid #dce2ee;border-radius:11px;
 background:#fff;box-shadow:0 12px 30px #222f4b27
}
.board-card-actions-list>button{
 display:block;width:100%;border:0;background:transparent;
 color:#36415b;text-align:left;padding:10px 11px;font:inherit;
 font-size:12px;font-weight:700;border-radius:7px;cursor:pointer
}
.board-card-actions-list>button:hover{background:#f0f3ff}
.board-card-actions-list>button.board-card-danger{color:#b13f53}
.board-card-actions-list>button.board-card-danger:hover{background:#fff0f2}
.board-card-actions-info{
 height:auto!important;overflow:visible!important;margin:0!important;
 padding:10px!important;font-size:12px!important;line-height:1.5!important
}


/* Board search and batch selection: preserve hidden display across card/table CSS. */
.board-card[hidden],.board-table tr[hidden],
.board-bulk-toolbar[hidden],.board-search-no-results[hidden]{display:none!important}
.board-search-result{font-size:11px;color:#8992a8;margin:0 0 12px}
.board-search-no-results{padding:22px;text-align:center;color:#7b849e}
.board-bulk-toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;
