  gap:19px;
  background:#f3f6fc;
}
.mrh-section-heading{letter-spacing:.1em}
.mrh-tracker-stats{
  grid-template-columns:repeat(6,minmax(0,1fr));
  gap:12px;
}
.mrh-tracker-stats>.mrh-kpi-card{
  min-width:0;
  min-height:138px;
  padding:16px;
  border-radius:13px;
  border-color:#e0e7f2;
  box-shadow:0 2px 8px rgba(26,49,86,.025);
  background:#fff;
}
.mrh-kpi-top{gap:8px;align-items:center;flex-wrap:nowrap}
.mrh-tracker-stats .mrh-kpi-top>span:last-child{
  font-size:.76rem;
  line-height:1.3;
}
.mrh-kpi-icon{
  width:29px;height:29px;border-radius:9px;
}
.mrh-tracker-stats>.mrh-kpi-card>strong{font-size:clamp(1.35rem,2vw,1.75rem)}
.mrh-tracker-stats>.mrh-kpi-protected>strong{font-size:1.04rem;letter-spacing:0}
.mrh-tracker-stats>.mrh-kpi-card>small{line-height:1.45}
.mrh-tracker-stats>.mrh-breakdown{gap:17px;justify-content:flex-start;padding:16px}
.mrh-breakdown-labels{gap:8px}
.mrh-breakdown-labels>strong{letter-spacing:.06em;line-height:1.35;white-space:normal}
.mrh-breakdown-labels>div{font-variant-numeric:tabular-nums;gap:7px}
.mrh-breakdown-labels>div b{min-width:14px;text-align:right}
.mrh-tracker-ratebar{
  background:#edf2fb;
  border:1px solid #dfe7f4;
  min-height:40px;
  border-radius:9px;
  padding:10px 14px;
}
.mrh-tracker-viewtabs{gap:5px;margin:0}
.mrh-tracker-viewtabs>*{padding:9px 12px}
.mrh-table-panel{
  border:1px solid #dee5f1;
  border-top:2px solid #6472ed;
  border-radius:13px;
  box-shadow:0 3px 12px rgba(28,46,82,.025);
}
.mrh-tracker-controls{gap:10px;padding:12px 13px;background:#fff}
.mrh-tracker-controls input[type=search],
.mrh-tracker-controls select{
