.mrh-tracker-overdue{background:#f8faff;min-height:40px}
.mrh-tracker-table-scroll{scrollbar-color:#b8c4d9 #f2f5fa;scrollbar-width:thin}
.mrh-tracker-table{font-size:.8rem}
.mrh-tracker-table th,.mrh-tracker-table td{padding:13px 14px}
.mrh-tracker-table thead th{background:#f1f5fb}
