.mrh-tracker-note{font-size:.74rem;line-height:1.5;color:#72829b}

/* Container queries follow available board width, not the browser viewport.
   This prevents six cramped cards inside the persistent CRM sidebar. */
@container (max-width:1130px){
 .mrh-tracker-stats{grid-template-columns:repeat(4,minmax(0,1fr))}
 .mrh-tracker-stats>.mrh-kpi-protected{grid-column:span 2}
 .mrh-tracker-stats>.mrh-breakdown{grid-column:span 2}
}
