 .mrh-tracker-stats{grid-template-columns:repeat(2,minmax(0,1fr))}
 .mrh-tracker-stats>.mrh-kpi-protected{grid-column:span 1}
 .mrh-tracker-stats>.mrh-breakdown{grid-column:span 2}
 .mrh-tracker-stats>.mrh-kpi-card{min-height:120px;padding:13px}
 .mrh-breakdown-ring{height:80px;width:80px}
