 position:sticky;top:0;
 height:100vh;height:100dvh;
 min-height:0;overflow:hidden;isolation:isolate;
 background:radial-gradient(ellipse 230px 140px at -20px -32px,#e6eaffb0,transparent 90%),
  linear-gradient(165deg,#fcfdff 0%,#f9faff 48%,#f7f9ff 100%);
 border-right:1px solid #e1e6f3;
 box-shadow:5px 0 25px #1a285206;
 color:var(--side-ink);
 display:flex;flex-direction:column
}
