/* frontend/user-role-experience.css */
/* CP-USER-ROLE-VIS01 — visual-only signed User Role Management surface.
   All selectors are scoped to #/user-role-management; never override shared RBAC UI. */
#app .aps-user-roles-shell{
 --ur-ink:#24314d;--ur-muted:#7886a2;--ur-line:#e3e9f4;--ur-indigo:#6064e8;
 background:radial-gradient(ellipse 72% 22% at 90% 0%,#e6ebff78,transparent 88%),#f6f8fd;
 min-width:0
}
#app .aps-user-roles-shell>.topbar{
 min-height:77px;position:relative;background:linear-gradient(90deg,#fff,#fbfcff);
 border-bottom:1px solid #e7ebf5
}
#app .aps-user-roles-shell .topbar .breadcrumb{gap:11px;font-size:12px;color:#8794ac}
#app .aps-user-roles-shell .topbar .breadcrumb strong{color:#32415e;font-weight:800}
#app .aps-user-roles-shell .topbar .top-actions{gap:12px}
#app .aps-user-roles-shell .topbar .top-pill{
 display:inline-flex;align-items:center;gap:8px;padding:10px 13px;
 border:1px solid #e3ebf3;border-radius:30px;background:#f8fbfc;
 color:#526983;font-size:11px;font-weight:790
}
#app .aps-user-roles-shell .topbar .online-dot{
 flex:none;width:7px;height:7px;border-radius:50%;
 background:#23b58d;box-shadow:0 0 0 3px #25b89420
}
#app .aps-user-roles-shell .topbar .top-avatar{
 display:grid;place-items:center;width:35px;height:35px;border-radius:12px;
 color:#fff;font-weight:850;background:linear-gradient(135deg,#a4a7ff,#665fe1);
 box-shadow:0 6px 15px #5e5ace2c;transition:transform .18s,box-shadow .18s
}
#app .aps-user-roles-shell .topbar .top-avatar:hover{
 transform:translateY(-1px);box-shadow:0 8px 21px #5555c743
}
#app .aps-user-roles-shell .topbar .top-avatar:focus-visible{
 outline:2px solid #5f66e9;outline-offset:3px
}
#app .aps-user-roles-shell>.main-content{
 max-width:1570px;padding:33px clamp(21px,3vw,49px) 90px
}
#app .aps-user-role-management{min-width:0;color:var(--ur-ink)}
#app .aps-user-role-management .role-icon{display:block;width:19px;height:19px;flex:none}
#app .aps-user-role-management .user-role-hero{
 position:relative;isolation:isolate;overflow:hidden;
 display:flex;align-items:center;justify-content:space-between;gap:24px;
 min-height:167px;margin:0 0 19px;padding:29px clamp(25px,3.2vw,46px);
 border:1px solid #293274;border-radius:22px;
 background:radial-gradient(ellipse 65% 150% at 100% 100%,#56529bbb,transparent 81%),
 radial-gradient(ellipse 80% 112% at 13% 0%,#3a4882,transparent 75%),
 linear-gradient(125deg,#151e44 0%,#222b5c 60%,#423c84 100%);
 box-shadow:0 20px 42px #1d2d6c20,0 2px 6px #1b245918
}
#app .aps-user-role-management .user-role-hero:after{
 content:"";position:absolute;z-index:-1;inset:0;pointer-events:none;
 background-image:linear-gradient(#ffffff05 1px,transparent 1px),
 linear-gradient(90deg,#ffffff05 1px,transparent 1px);background-size:40px 40px;
 mask-image:linear-gradient(90deg,transparent 20%,#0006 100%)
}
#app .aps-user-role-management .user-role-hero-copy,
#app .aps-user-role-management .user-role-refresh{position:relative;z-index:1}
#app .aps-user-role-management .user-role-hero-copy{min-width:0}
#app .aps-user-role-management .user-role-hero .label-top{
 display:inline-flex;align-items:center;gap:9px;color:#becbff;
 font-size:10px;letter-spacing:1.6px;font-weight:850
}
#app .aps-user-role-management .user-role-hero-dot{
 display:block;flex:none;width:6px;height:6px;border-radius:50%;
 background:#9bc5ff;box-shadow:0 0 0 4px #a5b9ff22
}
#app .aps-user-role-management .user-role-hero h1{
 color:#fff;font-size:clamp(26px,3vw,42px);font-weight:850;
 letter-spacing:-1.4px;line-height:1.15;margin:13px 0 9px;text-wrap:balance
}
#app .aps-user-role-management .user-role-heading-stop{color:#adbaff}
#app .aps-user-role-management .user-role-hero p{
 color:#cad4f0;font-size:13px;line-height:1.65;max-width:580px;margin:0
}
#app .aps-user-role-management .user-role-hero-decoration{
 position:absolute;z-index:0;top:-30px;right:-13px;width:min(45%,420px);
 height:auto;color:#edf2ff;opacity:.9;pointer-events:none
}
#app .aps-user-role-management .user-role-refresh{
 display:inline-flex;gap:9px;align-items:center;justify-content:center;flex:none;
 min-height:43px;padding:10px 16px;border:1px solid #cbd4ff64;border-radius:11px;
 color:#f5f6ff;background:#ffffff18;font-size:12px;font-weight:800;
 backdrop-filter:blur(5px);
 transition:transform .17s,background .17s,border-color .17s
}
#app .aps-user-role-management .user-role-refresh .role-icon{width:16px;height:16px}
#app .aps-user-role-management .user-role-refresh:hover:not(:disabled){
 transform:translateY(-2px);background:#ffffff2b;border-color:#dce1ff98
}
#app .aps-user-role-management .user-role-refresh:disabled{opacity:.62;cursor:not-allowed}
#app .aps-user-role-management .user-role-refresh:focus-visible{
 outline:2px solid #fff;outline-offset:3px
}
#app .aps-user-role-management .user-role-warning{
 display:flex;gap:13px;align-items:flex-start;
 border:1px solid #f1dcb5;border-left:3px solid #dfa95b;border-radius:13px;
 padding:16px 19px;margin:0 0 19px;
 background:linear-gradient(110deg,#fffaf2,#fff5eb);
 color:#865f36;font-size:11.5px;line-height:1.75;overflow-wrap:anywhere
}
#app .aps-user-role-management .user-role-warning-icon{
 display:grid;place-items:center;flex:none;width:35px;height:35px;
 border-radius:10px;background:#ffedd1;color:#ad7728
}
#app .aps-user-role-management .user-role-warning>div{min-width:0;flex:1}
#app .aps-user-role-management .user-role-stat-grid{
 display:grid;grid-template-columns:repeat(4,minmax(0,1fr));
 gap:14px;margin:0 0 23px
}
#app .aps-user-role-management .user-role-stat-card{
 isolation:isolate;position:relative;min-height:136px;
 overflow:hidden;border:1px solid #e3e9f4;border-radius:16px;
 padding:21px 19px;background:linear-gradient(150deg,#fff,#fcfdff);
 box-shadow:0 8px 25px #1e2f6711,0 1px 3px #1b265108;
 transition:transform .19s,box-shadow .19s,border-color .19s
}
#app .aps-user-role-management .user-role-stat-card:before{
 content:"";position:absolute;top:0;left:0;width:100%;height:3px;
 background:linear-gradient(90deg,#aba9fd,transparent 94%);opacity:.9
}
#app .aps-user-role-management .user-role-stat-roles:before{
 background:linear-gradient(90deg,#83cfb6,transparent 94%)
}
#app .aps-user-role-management .user-role-stat-boards:before{
 background:linear-gradient(90deg,#9ac5ec,transparent 94%)
}
#app .aps-user-role-management .user-role-stat-proposals:before{
 background:linear-gradient(90deg,#edb87c,transparent 94%)
}
@media(hover:hover) and (pointer:fine){
 #app .aps-user-role-management .user-role-stat-card:hover{
  transform:translateY(-3px);border-color:#cdd6f3;
  box-shadow:0 15px 31px #22356619
 }
}
#app .aps-user-role-management .user-role-stat-icon{
 display:grid;place-items:center;float:right;width:38px;height:38px;
 border-radius:11px;background:#eceeff;color:#6469e5
}
#app .aps-user-role-management .user-role-stat-roles .user-role-stat-icon{background:#e5f8f1;color:#249b83}
#app .aps-user-role-management .user-role-stat-boards .user-role-stat-icon{background:#e6f3ff;color:#438bc5}
#app .aps-user-role-management .user-role-stat-proposals .user-role-stat-icon{background:#fff0e2;color:#d38d48}
#app .aps-user-role-management .user-role-stat-card .stat-label{
 display:block;color:#7e8ba4;font-size:11px;font-weight:785;line-height:1.45;
 padding-right:37px
}
#app .aps-user-role-management .user-role-stat-card .stat-value{
 display:block;color:#24304d;font-size:32px;line-height:1.2;
 letter-spacing:-1.3px;font-weight:870;margin-top:18px;
 font-variant-numeric:tabular-nums;overflow-wrap:anywhere
}
#app .aps-user-role-management .user-role-selection-panel,
#app .aps-user-role-management .user-role-selected-panel,
#app .aps-user-role-management .user-role-platform-panel,
#app .aps-user-role-management .user-role-table-panel,
#app .aps-user-role-management .user-role-loading{
 overflow:hidden;border:1px solid #e4e9f4;border-radius:16px;
 background:#fff;box-shadow:0 9px 28px #2433690f;
 margin:0 0 18px
}
#app .aps-user-role-management .panel-header{
 display:flex;justify-content:space-between;align-items:center;gap:12px;
 padding:17px 20px;background:linear-gradient(90deg,#f5f6ff,#fafbff);
 border-bottom:1px solid #e7ebf5
}
#app .aps-user-role-management .panel-header h3{
 margin:0;color:#2f3b55;font-size:13px;font-weight:850;overflow-wrap:anywhere
}
#app .aps-user-role-management .panel-header span{
 color:#8591a9;font-size:10.5px;overflow-wrap:anywhere
}
#app .aps-user-role-management .panel-body{padding:20px}
#app .aps-user-role-management .user-role-selection-panel label{
 display:block;margin:0 0 10px;font-size:11px;
 color:#586780;font-weight:800
}
#app .aps-user-role-management .user-role-account-select{
 width:100%;min-height:47px;padding:11px 15px;
 color:#30405f;border:1px solid #dfe5f2;border-radius:11px;
 background:#fff;font-size:12px;
 box-shadow:0 3px 12px #24315f08;
 transition:border-color .17s,box-shadow .17s
}
#app .aps-user-role-management .user-role-account-select:focus-visible{
 outline:0;border-color:#656aea;box-shadow:0 0 0 4px #626be91b
}
#app .aps-user-role-management .user-role-protected{
 border:1px solid #f1dcb5;border-left:3px solid #dda963;
 border-radius:11px;padding:15px 17px;margin:0;
 background:#fff8ef;color:#805c33;font-size:11.5px;line-height:1.6
}
#app .aps-user-role-management .user-role-helper{
 background:#f3f6ff;color:#647491;border:1px solid #e1e7fa;
 border-radius:11px;padding:15px 17px;margin:0;
 font-size:11.5px;line-height:1.6
}
#app .aps-user-role-management .user-role-section-header{
 display:flex;gap:14px;align-items:center;justify-content:space-between;
 margin:30px 0 14px;min-width:0
}
#app .aps-user-role-management .user-role-section-header strong{
 color:#263550;font-size:18px;font-weight:850;
 letter-spacing:-.45px;line-height:1.3
}
#app .aps-user-role-management .user-role-ceiling-note{
 background:linear-gradient(110deg,#fffaf2,#fff6ed);
 color:#876036;border:1px solid #f2dfbd;border-left:3px solid #dca65d;
 border-radius:12px;padding:16px 18px;margin:0 0 17px;
 font-size:11.5px;line-height:1.75;overflow-wrap:anywhere
}
#app .aps-user-role-management .user-role-platform-panel .panel-body{
 display:grid;grid-template-columns:repeat(2,minmax(0,1fr));
 column-gap:18px;row-gap:14px;padding:23px
}
#app .aps-user-role-management .user-role-platform-panel .settings-detail{
 display:flex;flex-direction:column;justify-content:center;gap:9px;
 padding:16px 19px;margin:0;
 min-height:91px;border:1px solid #e7ebf5;border-radius:12px;
 background:#fafbff;min-width:0
}
#app .aps-user-role-management .user-role-platform-panel .settings-detail label{
 color:#818da5;font-size:9px;font-weight:840;letter-spacing:1px;
 text-transform:uppercase
}
#app .aps-user-role-management .user-role-platform-panel .settings-detail strong{
 color:#263751;font-size:14px;font-weight:820;overflow-wrap:anywhere
}
#app .aps-user-role-management .user-role-platform-panel .panel-body>button{
 justify-self:start;align-self:start;min-height:41px;
 margin:1px 8px 0 0;padding:10px 15px;
 border:1px solid #dbe2f1;border-radius:10px;
 color:#4b57a1;background:#fff;font-size:11.5px;font-weight:800;
 transition:background .17s,transform .17s
}
#app .aps-user-role-management .user-role-platform-panel .panel-body>button:hover:not(:disabled){
 background:#eef0ff;transform:translateY(-1px)
}
#app .aps-user-role-management .user-role-platform-panel .panel-body>button:disabled{
 color:#9ba5b8;background:#f6f7fb;cursor:not-allowed;opacity:.85
}
#app .aps-user-role-management .user-role-table-panel{max-width:100%}
#app .aps-user-role-management .user-role-table-scroll{
 overflow-x:auto;width:100%;max-width:100%;
 overscroll-behavior-x:contain;-webkit-overflow-scrolling:touch;
 scrollbar-width:thin;scrollbar-color:#cbd3eb transparent
}
#app .aps-user-role-management .user-role-table{
 min-width:670px;width:100%;border-collapse:separate;border-spacing:0;margin:0
}
#app .aps-user-role-management .user-role-table thead{
 background:linear-gradient(90deg,#f2f4ff,#f7f8ff)
}
#app .aps-user-role-management .user-role-table th{
 padding:17px 18px;white-space:nowrap;color:#7987a3;
 font-size:9px;font-weight:850;letter-spacing:1.05px;text-align:left;
 border-bottom:1px solid #e5e9f5
}
#app .aps-user-role-management .user-role-table td{
 padding:14px 18px;vertical-align:middle;
 border-bottom:1px solid #edf1f8;color:#53617f;
 font-size:11px;line-height:1.65;overflow-wrap:anywhere
}
#app .aps-user-role-management .user-role-table tbody tr:nth-child(even){background:#fcfdff}
#app .aps-user-role-management .user-role-table tbody tr:hover{background:#f5f6ff}
#app .aps-user-role-management .user-role-table tbody tr:last-child td{border-bottom:none}
#app .aps-user-role-management .user-role-table td strong{color:#2c3855;font-size:11.5px;font-weight:825}
#app .aps-user-role-management .user-role-table td button{
 min-height:34px;padding:7px 12px;margin:3px 5px 3px 0;
 border:1px solid #dbe2f1;border-radius:9px;background:#fff;
 color:#4a5a9c;font-size:10.5px;font-weight:780;
 transition:background .17s,transform .17s
}
#app .aps-user-role-management .user-role-table td button:hover:not(:disabled){
 background:#eef0ff;transform:translateY(-1px)
}
#app .aps-user-role-management .user-role-table td button:disabled{
 background:#f5f7fb;color:#99a3b8;opacity:.83;cursor:not-allowed
}
#app .aps-user-role-management .user-role-platform-panel button:focus-visible,
#app .aps-user-role-management .user-role-table button:focus-visible{
 outline:2px solid #6068e7;outline-offset:3px
}
#app .aps-user-role-management .user-role-board-note{
 padding:15px 18px;margin:0 0 16px;border-radius:11px;
 border:1px solid #dde6fc;border-left:3px solid #8397ec;
 color:#647491;background:linear-gradient(110deg,#f1f4ff,#f9faff);
 font-size:11.5px;line-height:1.75
}
#app .aps-user-role-management .user-role-boundary-note{
 display:flex;align-items:flex-start;gap:12px;margin:24px 0 0;
 padding:18px 19px;background:#f1f4fc;border:1px solid #e0e6f5;
 border-radius:12px;color:#5f6f8b;font-size:11.5px;line-height:1.7
}
#app .aps-user-role-management .user-role-boundary-note .role-icon{
 width:19px;height:19px;color:#626adb;flex:none
}
#app .aps-user-role-management .user-role-boundary-note span{flex:1;min-width:0}
#app .aps-user-role-management .user-role-loading{padding:20px}
#app .aps-user-role-management .error-banner:focus-visible{
 outline:2px solid #d33f5c;outline-offset:3px
}
@media(max-width:1250px){
 #app .aps-user-role-management .user-role-stat-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
 #app .aps-user-role-management .user-role-stat-card{min-height:124px}
}
@media(max-width:820px){
 #app .aps-user-role-management .user-role-hero{
  align-items:flex-start;flex-wrap:wrap;gap:19px;padding:25px 29px
 }
 #app .aps-user-role-management .user-role-hero-decoration{right:-65px;width:70%}
 #app .aps-user-role-management .user-role-platform-panel .panel-body{grid-template-columns:1fr}
}
@media(max-width:650px){
 #app .aps-user-roles-shell>.main-content{padding:20px 15px 65px}
 #app .aps-user-roles-shell>.topbar{min-height:64px}
 #app .aps-user-roles-shell .topbar .top-pill{display:none}
 #app .aps-user-role-management .user-role-hero{
  padding:23px 21px;border-radius:17px
 }
 #app .aps-user-role-management .user-role-hero h1{font-size:27px;letter-spacing:-.9px}
 #app .aps-user-role-management .user-role-hero p{font-size:12px}
 #app .aps-user-role-management .user-role-refresh{width:100%}
 #app .aps-user-role-management .user-role-warning{
  gap:10px;padding:14px;font-size:10.5px
 }
 #app .aps-user-role-management .user-role-stat-grid{gap:10px}
 #app .aps-user-role-management .user-role-stat-card{
  padding:16px 13px;min-height:112px;border-radius:14px
 }
 #app .aps-user-role-management .user-role-stat-icon{width:30px;height:30px}
 #app .aps-user-role-management .user-role-stat-icon .role-icon{width:16px;height:16px}
 #app .aps-user-role-management .user-role-stat-card .stat-label{
  font-size:10px;padding-right:22px
 }
 #app .aps-user-role-management .user-role-stat-card .stat-value{font-size:25px;margin-top:15px}
 #app .aps-user-role-management .panel-header{padding:15px}
 #app .aps-user-role-management .panel-body{padding:15px}
 #app .aps-user-role-management .user-role-section-header strong{font-size:16px}
 #app .aps-user-role-management .user-role-ceiling-note,
 #app .aps-user-role-management .user-role-board-note{font-size:10.5px}
 #app .aps-user-role-management .user-role-platform-panel .panel-body{padding:15px}
 #app .aps-user-role-management .user-role-platform-panel .panel-body>button{width:100%}
}
@media(max-width:395px){
 #app .aps-user-role-management .user-role-stat-grid{grid-template-columns:1fr}
 #app .aps-user-role-management .user-role-stat-card{min-height:100px}
}
@media(prefers-reduced-motion:reduce){
 #app .aps-user-role-management *,
 #app .aps-user-role-management *:before,
 #app .aps-user-role-management *:after,
 #app .aps-user-roles-shell .topbar *,
 #app .aps-user-roles-shell .topbar *:before,
 #app .aps-user-roles-shell .topbar *:after{
  animation:none!important;transition:none!important
 }
 #app .aps-user-role-management .user-role-stat-card:hover,
 #app .aps-user-role-management .user-role-refresh:hover,
 #app .aps-user-role-management .user-role-table button:hover{transform:none}
}
@media(prefers-contrast:more){
 #app .aps-user-role-management .user-role-hero{background:#18244e;border-color:#abb6e9}
 #app .aps-user-role-management .user-role-hero p{color:#fff}
 #app .aps-user-role-management .user-role-warning{color:#624116;border-color:#ab7d36}
 #app .aps-user-role-management .user-role-stat-card,
 #app .aps-user-role-management .user-role-table-panel{border-color:#748097}
 #app .aps-user-role-management .user-role-board-note{color:#405372;border-color:#6673a8}
}


/* CP-URM-QOL-01 — contextual action labels, readable tables, keyboard scroll. */
#app .aps-user-role-management .user-role-refresh,
#app .aps-user-role-management .user-role-platform-panel .panel-body>button,
#app .aps-user-role-management .user-role-table td button{
 min-height:44px
}
#app .aps-user-role-management .user-role-table td button{
 padding:10px 12px;font-size:12px
}
#app .aps-user-role-management .user-role-table th{
 font-size:11px;color:#53627f
}
#app .aps-user-role-management .user-role-table td{
 font-size:12px;color:#4e5e78
}
#app .aps-user-role-management .user-role-table td strong{font-size:12px}
#app .aps-user-role-management .user-role-table-scroll:focus-visible{
 outline:3px solid #626bf0;outline-offset:-3px;border-radius:10px
}
#app .aps-user-role-management .user-role-helper,
#app .aps-user-role-management .user-role-ceiling-note,
#app .aps-user-role-management .user-role-board-note,
#app .aps-user-role-management .user-role-warning{font-size:12px}
#app .aps-user-role-management .user-role-table-scroll{
 overscroll-behavior-x:contain
}
@media(max-width:650px){
 #app .aps-user-role-management .user-role-table-scroll{
  max-width:100%;-webkit-overflow-scrolling:touch
 }
 #app .aps-user-role-management .user-role-section-header{min-width:0}
}


/* CP-URM-FLOW-01: same-page application and board access, no nested routing. */
#app .aps-user-role-management .user-role-access-nav{
 display:flex;align-items:center;gap:6px;flex-wrap:wrap;
 padding:6px;margin:22px 0 19px;border:1px solid #e2e7f4;
 background:#f2f4fa;border-radius:13px
}
#app .aps-user-role-management .user-role-access-nav button{
 flex:1 1 170px;min-height:44px;padding:10px 14px;
 border-radius:9px;border:1px solid transparent;
 font-size:12px;font-weight:760;color:#53627d;
 background:transparent;cursor:pointer
}
#app .aps-user-role-management .user-role-access-nav button[aria-pressed="true"]{
 color:#37439a;border-color:#c9d0fa;background:#fff;
 box-shadow:0 2px 8px #24336913
}
#app .aps-user-role-management .user-role-access-nav button:focus-visible{
 outline:3px solid #5d63dd;outline-offset:2px
}
#app .aps-user-role-management .user-role-access-section[hidden]{display:none!important}
#app .aps-user-role-management .user-role-access-section{min-width:0}
@media(max-width:650px){
 #app .aps-user-role-management .user-role-access-nav{
  gap:4px;padding:4px
 }
 #app .aps-user-role-management .user-role-access-nav button{
