/* frontend/initialization-core.css */
/* APSYNTRA Neural Core: loading-only, removed as soon as bootstrap completes. */
.aps-init{
 position:fixed;inset:0;z-index:3000;display:grid;place-items:center;
 overflow:hidden;isolation:isolate;color:#eaf5ff;
 background:radial-gradient(ellipse at 50% 44%,#12336a 0%,#081a38 28%,#050f22 61%,#030814 100%);
 opacity:1;transition:opacity .24s ease-out;
}
.aps-init:before,.aps-init:after{content:"";position:absolute;inset:0;pointer-events:none}
.aps-init:before{
 background:radial-gradient(ellipse at 20% 10%,#2564d71a,transparent 40%),
 radial-gradient(ellipse at 82% 82%,#12d9f015,transparent 42%);
}
.aps-init:after{
 opacity:.17;
 background-image:linear-gradient(#2c78d31d 1px,transparent 1px),
 linear-gradient(90deg,#2c78d31d 1px,transparent 1px);
 background-size:70px 70px;
 -webkit-mask-image:radial-gradient(ellipse at 50% 52%,#000,transparent 72%);
 mask-image:radial-gradient(ellipse at 50% 52%,#000,transparent 72%);
}
.aps-init-exiting{opacity:0;pointer-events:none}
.aps-init-scene{position:absolute;inset:0;pointer-events:none;z-index:1}
.aps-init-canvas{display:block;width:100%;height:100%;pointer-events:none}
.aps-init-orb-fallback{
 position:absolute;z-index:1;width:min(55vw,430px);aspect-ratio:1;
 top:50%;left:50%;transform:translate(-50%,-62%);
 border:1px solid #36d7f965;border-radius:50%;
 background:radial-gradient(circle at 36% 32%,#64e4ff28,transparent 34%),
 radial-gradient(circle at center,#1d55d64d 0%,#0b1c4f6e 40%,transparent 72%);
 box-shadow:0 0 80px #0e8bff21,inset 0 0 90px #23c4fb14;
 animation:aps-orb 13s linear infinite;
}
.aps-init-orb-fallback:before,.aps-init-orb-fallback:after{
 content:"";position:absolute;inset:-13%;border:1px solid #42baff6b;
 border-radius:50%;transform:rotate(65deg) scaleY(.45);
 box-shadow:0 0 24px #1dc3ff36;
}
.aps-init-orb-fallback:after{transform:rotate(-45deg) scaleY(.6);inset:-6%;border-color:#4a6cf88a}
.aps-init[data-graphics="webgl"] .aps-init-orb-fallback{display:none}
.aps-init-content{position:relative;z-index:2;width:min(88vw,560px);
 margin-top:min(45vh,375px);text-align:center;padding:18px 20px 45px}
.aps-init-eyebrow{font:700 10px/1.4 Inter,system-ui,sans-serif;
 letter-spacing:.34em;color:#81baff;text-transform:uppercase}
.aps-init-name{font:800 clamp(30px,5vw,56px)/1.05 Inter,system-ui,sans-serif;
 letter-spacing:-.055em;margin:12px 0 6px;color:#fff;
 text-shadow:0 0 45px #4e8aff66}
.aps-init-name span{font-weight:360;color:#8fc7ff}
.aps-init-tagline{font:600 clamp(9px,1vw,12px)/1.5 Inter,system-ui,sans-serif;
 letter-spacing:.20em;color:#8cb1d4;margin:8px 0 34px}
.aps-init-readiness{width:min(100%,420px);margin:auto;display:grid;gap:12px}
.aps-init-track{height:3px;border-radius:10px;background:#2a50836b;overflow:hidden;position:relative}
.aps-init-track:before{content:"";position:absolute;width:28%;height:100%;left:-28%;
 background:linear-gradient(90deg,transparent,#60caff,#fff);border-radius:inherit;
 animation:aps-track 2s ease-in-out infinite}
.aps-init-details{display:flex;justify-content:space-between;align-items:center;gap:12px;
 color:#b3c8e0;font:500 12px/1.5 Inter,system-ui,sans-serif}
.aps-init-details span:last-child{font-size:10px;letter-spacing:.14em;color:#5da5db;text-transform:uppercase;white-space:nowrap}
.aps-init-status{min-height:20px;text-align:left}
.aps-init-footer{position:absolute;bottom:clamp(18px,4vh,38px);left:0;right:0;
 text-align:center;color:#6997c0;font:600 10px Inter,system-ui,sans-serif;letter-spacing:.24em}
@keyframes aps-track{to{left:120%}}
@keyframes aps-orb{to{transform:translate(-50%,-62%) rotate(360deg)}}
@media(max-width:600px){
 .aps-init-orb-fallback{width:68vw;top:44%}
 .aps-init-content{margin-top:40vh;padding-inline:16px}
 .aps-init-tagline{margin-bottom:26px}
 .aps-init-details{font-size:11px}
}
@media(max-height:600px){.aps-init-orb-fallback{width:min(36vh,250px);top:38%}
 .aps-init-content{margin-top:38vh;padding-bottom:20px}
 .aps-init-tagline{margin-bottom:16px}.aps-init-footer{bottom:12px}}
@media(prefers-reduced-motion:reduce){
 .aps-init,.aps-init-track:before,.aps-init-orb-fallback{animation:none;transition:none}
 .aps-init-exiting{opacity:0}
}


/* Fatal module bootstrap failure — accessible recovery within the existing overlay. */
.aps-init-recovery{margin:20px auto 0;padding:20px;max-width:420px;
 border:1px solid #88b9fa70;border-radius:14px;background:#061630eb;
 color:#ebf3ff;text-align:left;box-shadow:0 8px 25px #0005}
.aps-init-recovery h2{font:700 20px/1.3 Inter,system-ui,sans-serif;margin:0 0 10px}
.aps-init-recovery p{font:400 13px/1.6 Inter,system-ui,sans-serif;margin:0 0 17px;color:#c9def5}
.aps-init-retry{border:1px solid #add3ff;border-radius:9px;
 padding:11px 16px;background:#b9dbff;color:#092345;cursor:pointer;
 font:700 13px/1.4 Inter,system-ui,sans-serif;min-height:44px}
.aps-init-retry:focus-visible{outline:3px solid white;outline-offset:3px}
.aps-init[data-phase="fatal"] .aps-init-track:before{animation:none;display:none}
.aps-init[data-phase="fatal"] .aps-init-orb-fallback{animation:none}

/* frontend/time-tracker-gps.css */
/* CP-TT-GPS-UI-01. Scoped GPS work area based on the provided reference.
   No remote map tiles, fonts, monitoring, or employee coordinate requests. */
.tt-gps{
 --tt-gps-orange:#ed5c29;--tt-gps-ink:#282626;--tt-gps-muted:#797571;
 background:#f8f7f5;color:var(--tt-gps-ink);
 padding:clamp(20px,2.6vw,38px) clamp(12px,2.2vw,28px) 36px;
 font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
 min-width:0;
}
.tt-gps *{box-sizing:border-box}
.tt-gps-heading{display:flex;align-items:center;justify-content:space-between;gap:18px;flex-wrap:wrap;margin:0 auto 14px;max-width:1500px}
.tt-gps-heading h3{font:700 clamp(27px,2.7vw,36px)/1.16 Georgia,"Times New Roman",serif;margin:0 0 6px;letter-spacing:-.7px}
.tt-gps-heading p{margin:0;color:#77726e;font-size:13px;line-height:1.5}
.tt-gps-status{display:flex;align-items:center;gap:8px;color:#588766;font-weight:700;font-size:12px}
.tt-gps-status-dot{height:7px;width:7px;border-radius:50%;background:#72a07e;box-shadow:0 0 0 3px #e9f1e8}
.tt-gps-tabs{display:flex;align-items:center;gap:3px;overflow-x:auto;max-width:1500px;margin:0 auto 14px;border-top:1px solid #e6e1dd;border-bottom:1px solid #e6e1dd;padding:14px 0 0;scrollbar-width:thin}
.tt-gps-tab{display:inline-flex;align-items:center;justify-content:center;gap:9px;border:1px solid transparent;border-bottom:3px solid transparent;border-radius:6px 6px 0 0;background:transparent;padding:13px 17px;font-size:12px;font-weight:700;color:#9b9691;white-space:nowrap;min-height:43px}
.tt-gps-tab span{font-size:16px}
.tt-gps-tab:hover{color:#d8572d;background:#fff6f1}
.tt-gps-tab.is-current{color:#ea5b28;border:1px dashed #f2784d;border-bottom:3px solid #ed5c29;background:#fff7f1}
.tt-gps-controls,.tt-gps-compare-controls{display:flex;align-items:end;gap:10px;flex-wrap:wrap;max-width:1500px;margin:0 auto 14px;background:#fff;border:1px solid #e7e2dd;border-radius:9px;padding:12px 14px}
.tt-gps-controls label,.tt-gps-compare-controls label{display:flex;flex-direction:column;gap:6px;min-width:120px;font-size:11px;font-weight:650;color:#77726f}
.tt-gps-controls label:nth-child(3){min-width:190px;flex:1}
.tt-gps-controls input,.tt-gps-controls select,.tt-gps-compare-controls input,.tt-gps-compare-controls select{min-height:36px;width:100%;border:1px solid #ddd8d2;border-radius:6px;background:#fafaf9;color:#333;padding:6px 10px;font-size:12px;max-width:100%}
.tt-gps-controls button,.tt-gps-compare-controls button{display:inline-flex;align-items:center;justify-content:center;min-height:36px;padding:8px 14px;border:1px solid #efc0ac;border-radius:6px;background:#fff4ef;color:#d44f22;font-size:12px;font-weight:750}
.tt-gps-controls button:hover,.tt-gps-compare-controls button:hover{background:#ffeadf}
.tt-gps-map-shell{position:relative;max-width:1500px;min-height:450px;height:clamp(450px,57vh,760px);margin:0 auto;border:1px solid #c8cec9;overflow:hidden;background:#eaf0e7}
.tt-gps-map-canvas{position:absolute;inset:0;display:grid;place-items:center;overflow:hidden}
.tt-gps-map-svg{display:block;width:100%;height:100%}
.tt-gps-theme-dark{background:#25313a}
.tt-gps-map-stats{position:absolute;top:13px;left:13px;display:flex;align-items:stretch;z-index:1;background:#fff;border-radius:7px;box-shadow:0 2px 14px #1b27343d;padding:8px 4px;max-width:calc(100% - 26px)}
.tt-gps-map-stats .tt-gps-kpi{display:grid;gap:5px;align-content:center;padding:4px 17px;border-right:1px solid #ece9e6}
.tt-gps-map-stats .tt-gps-kpi span{font-size:9px;letter-spacing:1.1px;font-weight:800;color:#aaa39d;white-space:nowrap}
.tt-gps-map-stats .tt-gps-kpi strong{font-size:18px;color:#557e60;line-height:1}
.tt-gps-map-stats .tt-gps-kpi:nth-child(3) strong{color:#98908a}
.tt-gps-refresh{border:0;background:transparent;color:#75716c;font-size:25px;padding:0 12px}
.tt-gps-refresh:hover{color:#e75d2a}
.tt-gps-map-modes{position:absolute;top:13px;right:13px;z-index:2;display:flex;align-items:center;gap:1px;border-radius:8px;padding:3px;background:#fff;box-shadow:0 2px 15px #1727333b;max-width:calc(100% - 26px)}
.tt-gps-map-modes button{border:0;border-radius:5px;background:transparent;color:#3e4047;padding:9px 12px;font-size:11px;font-weight:700;white-space:nowrap}
.tt-gps-map-modes button.is-active{background:#f0f1f3;color:#222631}
.tt-gps-map-modes button:disabled{background:#f7f8fa;color:#9da1a7;cursor:not-allowed;opacity:1}
.tt-gps-map-zoom{position:absolute;top:76px;left:13px;z-index:1;display:grid;background:#fff;border-radius:5px;box-shadow:0 2px 12px #1b27343d;overflow:hidden}
.tt-gps-map-zoom button{height:35px;width:35px;background:#fff;border:0;border-bottom:1px solid #e7e8ec;color:#272a2b;font-size:23px;font-weight:600;line-height:1}
.tt-gps-map-zoom button:last-child{border-bottom:0}
.tt-gps-map-zoom button:hover:not(:disabled){background:#f6f6f5}
.tt-gps-map-footer{position:absolute;bottom:14px;left:14px;right:14px;display:flex;align-items:center;justify-content:space-between;gap:10px;pointer-events:none}
.tt-gps-map-footer span{font-size:10px;letter-spacing:.15px;font-weight:650;padding:7px 11px;border-radius:5px;color:#43555d;background:#ffffffed;box-shadow:0 1px 9px #23333a20}
.tt-gps-map-empty{display:grid;gap:11px;place-content:center;text-align:center;max-width:360px;margin:auto;padding:20px;color:#626d67}
.tt-gps-map-empty strong{font:700 21px Georgia,serif;color:#39443f}
.tt-gps-map-empty span{font-size:12px;line-height:1.6}
.tt-gps-theme-dark .tt-gps-map-empty{color:#b4c4c8}
.tt-gps-theme-dark .tt-gps-map-empty strong{color:#f5f6f4}
.tt-gps-legend{display:flex;align-items:center;flex-wrap:wrap;gap:16px;max-width:1500px;margin:11px auto 18px;color:#7b7773;font-size:11px}
.tt-gps-legend span{display:inline-flex;align-items:center;gap:6px}
.tt-gps-legend i{display:inline-block;width:8px;height:8px;border-radius:50%}
.tt-gps-legend-in{background:#f15c2a}.tt-gps-legend-out{background:#2879be}
.tt-gps-legend span:last-child{margin-left:auto;color:#92908c}
.tt-gps-panel{max-width:1500px;margin:0 auto 15px;background:#fff;border:1px solid #e5e1dc;border-radius:9px;padding:19px;min-width:0}
.tt-gps-panel-head{display:flex;align-items:start;justify-content:space-between;gap:14px;border-bottom:1px solid #f0eeec;padding-bottom:14px;margin-bottom:10px}
.tt-gps-panel-head h4{font:700 17px/1.3 Georgia,"Times New Roman",serif;margin:0 0 6px}
.tt-gps-panel-head p{font-size:11px;color:#8f8985;margin:0}
.tt-gps-records{list-style:none;margin:0;padding:0;display:grid}
.tt-gps-records li{display:flex;align-items:center;gap:13px;flex-wrap:wrap;padding:13px 4px;border-bottom:1px solid #f1eeeb;min-width:0;font-size:12px}
.tt-gps-records li:last-child{border-bottom:0}
.tt-gps-record-pin{font-size:17px;color:#e75b2c}
.tt-gps-record-person{flex:1 1 155px;min-width:0}
.tt-gps-record-person strong,.tt-gps-record-person small,.tt-gps-record-fix span,.tt-gps-record-fix small{display:block;overflow-wrap:anywhere}
.tt-gps-record-person strong{color:#34312f}.tt-gps-record-person small,.tt-gps-record-fix small{color:#8b8580;margin-top:4px;font-size:11px}
.tt-gps-record-fix{flex:1 1 200px}
.tt-gps-record-link{margin-left:auto;border:1px solid #eae1db;border-radius:6px;color:#d75c2b;padding:8px 11px;font-weight:700;font-size:11px}
.tt-gps-record-link:hover{background:#fff3ed}
.tt-gps-kpis{display:flex;flex-wrap:wrap;gap:10px;margin:0 auto 15px;max-width:1500px}
.tt-gps-kpis .tt-gps-kpi{display:grid;gap:7px;min-width:138px;flex:1;background:#fff;border:1px solid #e5e1dc;border-radius:8px;padding:15px}
.tt-gps-kpis .tt-gps-kpi span{font-size:10px;font-weight:700;color:#8c8680}
.tt-gps-kpis .tt-gps-kpi strong{font-size:23px;color:#c9582e}
.tt-gps-note{max-width:1500px;margin:0 auto 14px;font-size:11px;line-height:1.65;color:#7e7873}
.tt-gps-privacy{padding:8px 0;color:#8b857e}
.tt-gps-bars{display:grid;gap:14px;padding:10px 4px}
.tt-gps-bar{display:grid;grid-template-columns:minmax(80px,130px) minmax(0,1fr) minmax(45px,85px);align-items:center;gap:11px;font-size:12px}
.tt-gps-bar progress{width:100%;height:11px;accent-color:#ef6232}
.tt-gps-bar strong{text-align:right;color:#333;font-size:12px}
.tt-gps-empty-list{font-size:12px;color:#85807a;text-align:center;padding:20px}
.tt-gps-restricted,.tt-gps-error{padding:14px;color:#ac4027;background:#fff2ec;border:1px solid #f3cbb9;border-radius:7px;font-size:12px}
.tt-gps-loading{font-size:12px;color:#7f7972;max-width:1500px;margin:0 auto 10px}
.tt-gps :is(button,input,select,a):focus-visible{outline:3px solid #f6a67c;outline-offset:2px}
@media(max-width:840px){
 .tt-gps-heading{align-items:flex-start}
 .tt-gps-map-shell{height:clamp(400px,54vh,600px)}
 .tt-gps-map-stats{top:12px;left:10px;padding:6px 0}
 .tt-gps-map-stats .tt-gps-kpi{padding:4px 12px}
 .tt-gps-map-modes{top:76px;right:10px}
 .tt-gps-map-zoom{top:88px;left:10px}
 .tt-gps-legend span:last-child{margin-left:0}
}
@media(max-width:520px){
 .tt-gps{padding:18px 10px 25px}
 .tt-gps-heading h3{font-size:27px}
 .tt-gps-controls label,.tt-gps-compare-controls label{flex:1 1 125px}
 .tt-gps-controls label:nth-child(3){flex-basis:100%}
 .tt-gps-controls .tt-gps-load{width:100%}
 .tt-gps-map-shell{height:440px;min-height:440px}
 .tt-gps-map-stats{left:6px;right:6px;max-width:none;justify-content:space-between;overflow:hidden}
 .tt-gps-map-stats .tt-gps-kpi{padding:4px 8px}
 .tt-gps-map-stats .tt-gps-kpi span{font-size:8px}
 .tt-gps-map-stats .tt-gps-kpi strong{font-size:16px}
 .tt-gps-refresh{padding:0 7px}
 .tt-gps-map-modes{top:77px;right:7px;max-width:calc(100% - 60px)}
 .tt-gps-map-modes button{padding:8px}
 .tt-gps-map-modes button span{font-size:10px}
 .tt-gps-map-zoom{top:77px;left:7px}
 .tt-gps-map-footer span{font-size:9px}
 .tt-gps-record-link{margin-left:0}
 .tt-gps-bar{grid-template-columns:70px minmax(0,1fr) 60px}
}
@media(prefers-reduced-motion:reduce){.tt-gps *{scroll-behavior:auto!important;transition:none!important}}


/* CP-TT-LEAFLET-01: Leaflet controls stay below TimeTracker filters. */
.tt-gps-map-canvas{display:block}
.tt-gps-map-canvas .tt-map-host{position:absolute;inset:0;min-height:100%;width:100%}
.tt-gps-map-shell .leaflet-top.leaflet-left{top:110px;left:10px}
.tt-gps-map-shell .leaflet-bottom.leaflet-left{bottom:30px}
.tt-gps-map-shell .leaflet-bottom.leaflet-right{bottom:30px}
.tt-gps-map-modes,.tt-gps-map-stats{z-index:500}
.tt-gps-map-footer{z-index:450;pointer-events:none}
@media(max-width:650px){.tt-gps-map-shell .leaflet-top.leaflet-left{top:145px}}

/* frontend/board-visual-refresh.css */
/* APSYNTRA CRM — Board visual system v2.
   Deliberately scoped to board routes across all 12 application boards.
   Static CSS only: no WebGL/canvas layers, entrance animations or layout rewrites.
   Keep signed session UI, native group scrolling, sticky columns and data intact. */

#app .aps-board-shell {
  --board-ink: #202b4d;
  --board-muted: #70809c;
  --board-indigo: #5459e4;
  --board-line: #dce4f3;
  --board-table-head: #eaf0fc;
  background: linear-gradient(180deg, #f0f4fd 0, #f7f9ff 470px, #f8faff 100%);
  min-height: calc(100vh - 77px);
  color: var(--board-ink);
}

/* 7, 8 — Persistent workspace top bar and signed identity. */
#app .aps-board-shell > .topbar {
  background: #ffffff;
  border-bottom: 1px solid #dbe5f7;
  box-shadow: 0 1px 0 #ffffff, 0 2px 12px #263c7610;
}
#app .aps-board-shell .topbar .breadcrumb {
  color: #8291b3;
  letter-spacing: .01em;
}
#app .aps-board-shell .topbar .breadcrumb strong {
  color: #293a66;
  font-weight: 750;
}
#app .aps-board-shell .top-actions .top-pill {
  background: #eefbf6;
  color: #22684e;
  border: 1px solid #caecdb;
}
#app .aps-board-shell .top-actions .top-avatar {
  box-shadow: 0 0 0 3px #f0efff;
}

/* 1, 2, 9 — Clearly differentiated board hero and actions. */
#app .aps-board-shell > .main-content {
  padding-top: clamp(20px, 2.6vw, 34px);
}
#app .aps-board-shell .page-head {
  position: relative;
  isolation: isolate;
  min-height: 158px;
  padding: clamp(24px, 3vw, 36px);
  border: 1px solid #324780;
  border-radius: 21px;
  background:
    radial-gradient(ellipse at 91% 13%, #7b75df69 0, #7b75df00 48%),
    linear-gradient(117deg, #17234b 0%, #253c7b 57%, #36377f 100%);
  box-shadow: 0 12px 30px #1d32611a;
  align-items: center;
  margin-bottom: 20px;
}
#app .aps-board-shell .page-head::before {
  content: "";
  position: absolute;
  inset: auto 30px 0 30px;
  height: 3px;
  border-radius: 8px 8px 0 0;
  background: linear-gradient(90deg, #77c4ff, #7779ff 58%, transparent);
  opacity: .9;
  pointer-events: none;
}
#app .aps-board-shell .page-head .label-top {
  color: #a8c7ff;
  letter-spacing: .16em;
  font-weight: 800;
}
#app .aps-board-shell .page-head h1 {
  color: #ffffff;
  font-size: clamp(27px, 2.35vw, 37px);
  letter-spacing: -.035em;
  line-height: 1.16;
  margin: 11px 0 9px;
}
#app .aps-board-shell .page-head p {
  color: #d1dffc;
  font-size: 12px;
  line-height: 1.6;
  max-width: 680px;
}
#app .aps-board-shell .page-head .head-actions {
  align-items: center;
  gap: 8px;
}
#app .aps-board-shell .page-head .head-actions > .secondary,
#app .aps-board-shell .page-head .head-actions > .primary,
#app .aps-board-shell .page-head .board-actions-menu > summary {
  min-height: 39px;
  border: 1px solid #ffffff5c;
  border-radius: 10px;
  color: #ffffff;
  background: #ffffff1b;
  box-shadow: none;
  font-size: 12px;
  font-weight: 740;
  padding: 10px 13px;
  transform: none;
  transition: background-color .14s ease, border-color .14s ease;
}
#app .aps-board-shell .page-head .head-actions > .primary {
  background: #e7e9ff;
  color: #283577;
  border-color: #e7e9ff;
}
#app .aps-board-shell .page-head .head-actions > .secondary:hover,
#app .aps-board-shell .page-head .board-actions-menu > summary:hover {
  background: #ffffff30;
  border-color: #ffffffb0;
  transform: none;
}
#app .aps-board-shell .page-head .head-actions > .primary:hover {
  background: #ffffff;
  color: #26346f;
  transform: none;
}
#app .aps-board-shell .page-head .board-actions-menu > summary::after {
  color: #d5dfff;
}
#app .aps-board-shell .page-head .board-actions-popover {
  background: #ffffff;
  color: #283754;
  border-color: #d9e1f0;
  box-shadow: 0 14px 30px #12224732;
}
#app .aps-board-shell .page-head :is(button, summary):focus-visible {
  outline: 3px solid #b4ddff;
  outline-offset: 2px;
}

/* 3 — Readable, clearly active views; no movement or spring feedback. */
#app .aps-board-shell .tabs.board-draggable-tabs {
  margin-bottom: 19px;
  padding: 6px;
  border: 1px solid #dde5f4;
  border-radius: 14px;
  background: #e9eefa;
  box-shadow: inset 0 1px 2px #2338650b;
  gap: 5px;
}
#app .aps-board-shell .board-tab-slot {
  min-height: 38px;
  gap: 3px;
}
#app .aps-board-shell .board-tab-slot > .tab {
  min-height: 37px;
  padding: 9px 12px;
  margin-bottom: 0;
  border: 1px solid transparent;
  border-radius: 9px;
  background: transparent;
  color: #647391;
  font-size: 12px;
  line-height: 1.4;
  font-weight: 730;
  transition: color .14s ease, background-color .14s ease;
}
#app .aps-board-shell .board-tab-slot > .tab:hover {
  color: #273b81;
  background: #ffffffa8;
}
#app .aps-board-shell .board-tab-slot > .tab.active,
#app .aps-board-shell .board-tab-slot > .tab[aria-selected="true"] {
  color: #ffffff;
  border-color: #4a51d9;
  background: #5056da;
  box-shadow: 0 2px 6px #3842ad2d;
}
#app .aps-board-shell .board-tab-slot > .tab.active:hover {
  background: #424bc7;
  color: #ffffff;
}
#app .aps-board-shell .board-tab-slot > .tab.active .csp-u060 {
  color: #f0f0ff;
}
#app .aps-board-shell .board-tab-slot .board-tab-reorder {
  min-width: 24px;
  min-height: 26px;
  padding: 2px 4px;
  background: #ffffffb6;
  border: 1px solid #d6def0;
  color: #63759c;
  border-radius: 7px;
}
#app .aps-board-shell .board-tab-slot .board-tab-reorder:hover {
  background: #ffffff;
  color: #4a53bd;
}

/* 4 — Give board tools an intentional, full-width command surface. */
#app .aps-board-shell .toolbar.board-customize-toolbar {
  padding: 14px;
  margin-bottom: 20px;
  gap: 9px;
  background: #ffffff;
  border: 1px solid #dce4f2;
  border-radius: 15px;
  box-shadow: 0 3px 16px #243c7110;
}
#app .aps-board-shell .board-customize-toolbar .search-wrap .search-input {
  min-height: 40px;
  background: #f6f8fe;
  border: 1px solid #dce4f3;
  color: #233256;
}
#app .aps-board-shell .board-customize-toolbar .search-wrap .search-input:focus {
  background: #ffffff;
  border-color: #7b85ee;
  box-shadow: 0 0 0 3px #e9ebff;
}
#app .aps-board-shell .board-customize-toolbar > .secondary,
#app .aps-board-shell .board-column-menu > summary {
  background: #f6f8ff;
  border: 1px solid #dce3f2;
  color: #354775;
  border-radius: 9px;
  font-size: 12px;
  font-weight: 730;
  box-shadow: none;
  transition: background-color .14s ease, border-color .14s ease;
}
#app .aps-board-shell .board-customize-toolbar > .secondary:hover,
#app .aps-board-shell .board-column-menu > summary:hover {
  background: #eaf0ff;
  border-color: #b9c8ed;
}
#app .aps-board-shell .board-customize-toolbar > .secondary:focus-visible,
#app .aps-board-shell .board-column-menu > summary:focus-visible {
  outline: 2px solid #5166d9;
  outline-offset: 2px;
}

/* 5 — Group headers as purposeful, separated information surfaces. */
#app .aps-board-shell .group-heading {
  min-height: 54px;
  padding: 10px 14px;
  margin: 22px 0 9px;
  border: 1px solid #dce5f3;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 2px 9px #2941790c;
}
#app .aps-board-shell .group-heading::before {
  height: 26px;
  width: 5px;
  flex: none;
  border-radius: 5px;
  background: linear-gradient(180deg, #6e76ff, #446cda);
}
#app .aps-board-shell .group-heading h3 {
  font-size: 13px;
  font-weight: 800;
  color: #24375d;
}
#app .aps-board-shell .group-heading small {
  display: inline-flex;
  padding: 4px 9px;
  border-radius: 99px;
  background: #edf1ff;
  color: #6674ab;
  font-size: 10px;
  font-weight: 740;
}
#app .aps-board-shell .group-heading .board-group-actions {
  margin-left: auto;
}
#app .aps-board-shell .group-heading .board-group-actions > summary {
  border-radius: 8px;
}
#app .aps-board-shell .group-heading.board-group-editing {
