/* frontend/board-import.css */
/* BIMP-04: focused import dialog styles, isolated from the board grid. */
.aps-import-overlay{position:fixed;inset:0;z-index:10050;background:rgba(5,9,15,.78);display:grid;place-items:center;padding:12px;color:#ecf0f7}
.aps-import-dialog{width:min(1050px,100%);height:min(94vh,900px);display:flex;flex-direction:column;background:#101418;border:1px solid #424a58;border-radius:14px;box-shadow:0 30px 96px #0009;overflow:hidden;color:inherit;font:inherit}
.aps-import-head{min-height:62px;display:flex;align-items:center;gap:20px;padding:14px 24px;border-bottom:1px solid #353e49}
.aps-import-head>strong{font-size:15px;white-space:nowrap}
.aps-import-steps{display:flex;justify-content:center;align-items:center;flex:1;gap:16px;flex-wrap:wrap}
.aps-import-steps>span{display:inline-flex;align-items:center;gap:7px;color:#9ba9bb;font-size:12px}
.aps-import-steps b{display:grid;place-items:center;width:23px;height:23px;border:1px solid #6b7482;border-radius:50%;font-weight:600}
.aps-import-steps .active{color:#fff}.aps-import-steps .active b{border-color:#1680ff;background:#1673db;color:#fff}
.aps-import-steps .done b{background:#1673db;border-color:#1673db;color:#fff}
.aps-import-close{border:0!important;background:transparent!important;color:#e9eef5!important;font-size:27px!important;line-height:1;cursor:pointer}
.aps-import-body{flex:1;min-height:0;overflow-y:auto;padding:24px;overscroll-behavior:contain}
.aps-import-center{min-height:100%;display:grid;place-items:center}
.aps-import-drop{width:min(490px,100%);min-height:180px;border:1px dashed #7b899a;border-radius:11px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:24px;text-align:center}
.aps-import-drop:hover,.aps-import-drop:focus-within{border-color:#2485ff;box-shadow:0 0 0 2px #2485ff33}
.aps-import-drop h2{font-size:19px;font-weight:500;margin:0}.aps-import-drop p{font-size:13px;color:#b0bbc8;margin:0}
.aps-import-config,.aps-import-match-screen{max-width:840px;margin:0 auto}
.aps-import-config h2,.aps-import-match-screen h2,.aps-import-success h2{font-size:20px;margin:2px 0 8px;text-align:center;color:#edf2fa}
.aps-import-config>p,.aps-import-match-screen>p{text-align:center;color:#aebaca;font-size:13px}
.aps-import-controls{display:flex;align-items:end;justify-content:center;flex-wrap:wrap;gap:16px;margin:24px 0}
.aps-import-dialog label{display:flex;flex-direction:column;gap:6px;font-size:13px;color:#d6dfeb}
.aps-import-dialog select,.aps-import-dialog input:not([type=radio]):not([type=checkbox]):not([type=file]){
 min-height:36px;background:#20262e;color:#f0f3f8;border:1px solid #626c7a;border-radius:6px;padding:7px 10px;max-width:100%;width:100%}
.aps-import-dialog select:focus-visible,.aps-import-dialog input:focus-visible,.aps-import-dialog button:focus-visible{outline:2px solid #2087ff;outline-offset:2px}
.aps-import-dialog button.primary{background:#0073eb;color:white;border:1px solid #1985ff;border-radius:6px;padding:9px 16px;min-height:36px}
.aps-import-dialog button.secondary{background:#252c35;color:#e5ebf5;border:1px solid #6a7481;border-radius:6px;padding:9px 16px;min-height:36px}
.aps-import-dialog button:disabled{opacity:.46;cursor:not-allowed}
.aps-import-mapping{border:1px solid #4b5563;border-radius:8px;overflow:hidden}
.aps-import-map-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;align-items:start;padding:12px 18px}
.aps-import-map-heading{background:#272e37;font-weight:650;font-size:13px}
.aps-import-map-row{border-top:1px solid #404955;font-size:14px;min-height:64px}
.aps-import-map-row b{display:block;font-weight:500;overflow-wrap:anywhere}
.aps-import-map-row small{display:block;color:#99a9bb;font-size:11px;margin-top:4px;overflow-wrap:anywhere}
.aps-import-proposed{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}
.aps-import-proposed label{font-size:11px}
.aps-import-permission{margin:22px 0;padding:17px;border:1px solid #4571ad;background:#142033;border-radius:9px}
.aps-import-permission h3,.aps-import-summary h3{margin:0 0 6px;font-size:16px}
.aps-import-permission p,.aps-import-summary p{font-size:13px;color:#b9c6d5;overflow-wrap:anywhere}
.aps-import-choice{display:flex;gap:10px;flex-wrap:wrap;margin:12px 0}
.aps-import-match-screen{max-width:560px}
.aps-import-match{display:flex!important;flex-direction:row!important;align-items:flex-start;gap:14px;margin:12px 0;padding:15px;border:1px solid #596473;border-radius:9px;cursor:pointer}
.aps-import-match.selected{border-color:#187cff;background:#15243a}
.aps-import-match input{margin-top:3px;accent-color:#137fff}
.aps-import-match span{display:flex;flex-direction:column;gap:5px}
.aps-import-match small{color:#b6c3d1;font-size:12px}
.aps-import-summary{margin:20px 0 6px;padding:16px;border-top:1px solid #4b5665}
.aps-import-final-check{flex-direction:row!important;align-items:start;gap:10px!important;margin-top:16px}
.aps-import-error{margin:16px auto;color:#ffd0d0;background:#582024;border:1px solid #ce646c;border-radius:7px;padding:10px 13px;max-width:840px}
.aps-import-success{display:flex;min-height:100%;justify-content:center;align-items:center;flex-direction:column;text-align:center;color:#cfe3fa}
.aps-import-footer{min-height:66px;border-top:1px solid #414954;padding:12px 24px;display:flex;align-items:center;gap:12px}
.aps-import-fill{flex:1}
@media(max-width:700px){
 .aps-import-overlay{padding:0}
 .aps-import-dialog{height:100dvh;border-radius:0}
 .aps-import-head,.aps-import-footer{padding:12px}
 .aps-import-steps{gap:7px}
 .aps-import-steps>span{font-size:10px}
 .aps-import-body{padding:14px}
 .aps-import-map-grid{gap:8px;padding:10px;grid-template-columns:42% minmax(0,58%)}
 .aps-import-proposed{grid-template-columns:1fr}
}
@media(prefers-reduced-motion:reduce){.aps-import-dialog *{scroll-behavior:auto;transition:none!important}}

/* CMP-01: explicitly consented choice-column setup, never an implicit import side effect. */
.aps-import-choice-config{margin-top:12px;padding:12px 14px;border:1px solid #4d7296;border-radius:8px;background:#142238;display:grid;gap:9px}
.aps-import-choice-config p{margin:0;color:#cbd7e6;font-size:12px;overflow-wrap:anywhere}
.aps-import-choice-config .aps-import-choice-consent{display:flex;flex-direction:row;align-items:flex-start;gap:9px;line-height:1.45;font-size:12px}
.aps-import-choice-config input[type="checkbox"]{flex:none;accent-color:#218cff;width:17px;height:17px;margin:0}
.aps-import-choice-config button{justify-self:start;font-size:12px}
.aps-import-choice-config button:disabled{opacity:.5}

/* CMP-01 import gate repair: surface a pending choice setup at the current scroll
   position without suggesting ordinary-column consent includes Status/Dropdown. */
.aps-import-resolve{margin:16px 0;padding:16px;border:1px solid #d4a347;border-radius:9px;background:#302619;display:grid;gap:10px}
.aps-import-resolve h3{font-size:15px;margin:0;color:#fff4dd}
.aps-import-resolve p{font-size:12px;color:#f2dbb7;line-height:1.5;margin:0}
.aps-import-resolve-row{border-top:1px solid #947242;padding-top:10px;display:grid;gap:4px}
.aps-import-resolve-row strong{font-size:13px;overflow-wrap:anywhere}
.aps-import-resolve .aps-import-choice{margin:4px 0}
.aps-import-resolve button{font-size:12px;white-space:normal;text-align:center}
.aps-import-excluded{padding:10px 12px;border-radius:7px;background:#25313e;border:1px solid #557086;color:#e6edf5;font-size:12px}
.aps-import-notice{margin:16px auto;color:#daf8e8;background:#193e32;border:1px solid #42a87f;border-radius:7px;padding:10px 13px;max-width:840px}
@media(max-width:600px){.aps-import-resolve .aps-import-choice{flex-direction:column;align-items:stretch}}

/* frontend/board-loading.css */
/* CP-BOARD-LOAD-01 — signed board-loading presentation only.
   100% native CSS: two modest compositor rotations, one progress sweep,
   zero layout-animated properties, no canvas, no runtime graphics resources. */
#app .aps-board-shell .aps-board-loading-head{
 min-height:122px;
 margin-bottom:14px;
}
#app .aps-board-shell .aps-board-loading-head h1{
 font-size:clamp(25px,2.4vw,34px);
}
#app .aps-board-shell .aps-board-loading{
 --bl-ink:#eaf4ff;
 --bl-muted:#abc5ef;
 position:relative;
 overflow:hidden;
 isolation:isolate;
 width:100%;
 box-sizing:border-box;
 min-height:334px;
 padding:clamp(19px,3.4vw,38px);
 border:1px solid #3a548f;
 border-radius:21px;
 color:var(--bl-ink);
 background:
  radial-gradient(ellipse at 17% 31%,#2a67b553 0%,transparent 40%),
  radial-gradient(ellipse at 96% 95%,#585ad64b 0%,transparent 56%),
  linear-gradient(125deg,#101b3e 0%,#162953 55%,#252b65 100%);
 box-shadow:0 13px 33px #1d336a21;
}
#app .aps-board-shell .aps-board-loading::before{
 content:"";
 position:absolute;inset:0;
 pointer-events:none;
 background-image:
  linear-gradient(#8bbdff0a 1px,transparent 1px),
  linear-gradient(90deg,#8bbdff0a 1px,transparent 1px);
 background-size:37px 37px;
 mask-image:linear-gradient(100deg,#0004,transparent 77%);
}
#app .aps-board-shell .aps-board-loading-stage{
 position:relative;z-index:1;
 display:grid;
 grid-template-columns:minmax(186px,265px) minmax(0,1fr);
 align-items:center;
 gap:clamp(18px,4vw,51px);
 min-height:205px;
}
#app .aps-board-shell .aps-board-loading-visual{
 position:relative;
 display:grid;
 place-items:center;
 width:min(100%,250px);
 aspect-ratio:1;
 justify-self:center;
}
#app .aps-board-shell .aps-board-loading-halo{
 position:absolute;inset:21%;
 border-radius:50%;
 background:radial-gradient(circle,#4a9ffa5c 0%,#437cdd25 45%,transparent 72%);
 filter:blur(14px);
 animation:aps-board-loading-glow 2.6s ease-in-out infinite alternate;
}
#app .aps-board-shell .aps-board-loading-orbit{
 position:absolute;
 display:block;
 border-radius:50%;
 border:1px solid #66b9ff70;
 box-shadow:0 0 13px #56b8ff21,inset 0 0 12px #56b8ff13;
}
#app .aps-board-shell .aps-board-loading-orbit-outer{
 inset:13%;
 border-color:#61aefa79;
 border-left-color:#94a1fa15;
 border-bottom-color:#7389fb29;
 transform:rotate(-24deg) scaleY(.72);
 animation:aps-board-loading-orbit-a 9s linear infinite;
}
#app .aps-board-shell .aps-board-loading-orbit-inner{
 inset:22%;
 border-width:2px;
 border-color:#7d8ff544;
 border-top-color:#a1ceffb2;
 border-right-color:#79acfe8a;
 transform:rotate(35deg) scaleX(.73);
 animation:aps-board-loading-orbit-b 7s linear infinite;
}
#app .aps-board-shell .aps-board-loading-core{
 position:relative;
 display:grid;place-items:center;
 width:83px;height:83px;
 border-radius:23px;
 background:linear-gradient(145deg,#224885,#151d49 70%);
 border:1px solid #9bceff91;
 box-shadow:inset 0 0 17px #377bcb3b,0 9px 30px #040b2f88,0 0 27px #327dce29;
}
#app .aps-board-shell .aps-board-loading-glyph{
 font-weight:900;
 font-size:47px;
 letter-spacing:-.12em;
 padding-right:.12em;
 line-height:1;
 color:#c2e7ff;
 text-shadow:0 0 20px #5fbfff6b;
}
#app .aps-board-shell .aps-board-loading-satellite{
 position:absolute;
 width:6px;height:6px;
 background:#8fe9fe;
 border-radius:50%;
 box-shadow:0 0 0 4px #71c8fe1c,0 0 13px #84e5ffad;
}
#app .aps-board-shell .aps-board-loading-satellite-a{top:25%;right:20%}
#app .aps-board-shell .aps-board-loading-satellite-b{bottom:20%;left:26%;width:4px;height:4px}
#app .aps-board-shell .aps-board-loading-copy{
 min-width:0;
 max-width:690px;
}
#app .aps-board-shell .aps-board-loading-eyebrow{
 color:#9bbff2;
 letter-spacing:.18em;
 font-size:10px;
 font-weight:800;
}
#app .aps-board-shell .aps-board-loading-copy h2{
 margin:12px 0 8px;
 font-size:clamp(22px,2.5vw,32px);
 line-height:1.16;
 font-weight:790;
 letter-spacing:-.035em;
 color:#fff;
}
#app .aps-board-shell .aps-board-loading-message{
 font-size:13px;
 line-height:1.55;
 color:#d2e3ff;
 margin:0 0 21px;
}
#app .aps-board-shell .aps-board-loading-progress{
 position:relative;
 overflow:hidden;
 width:min(100%,405px);
 height:4px;
 border-radius:50px;
 background:#ffffff1b;
}
#app .aps-board-shell .aps-board-loading-progress-beam{
 position:absolute;
 inset:0 auto 0 0;
 display:block;
 width:36%;
 border-radius:inherit;
 background:linear-gradient(90deg,transparent,#5bb5fd 42%,#adcfff 82%,transparent);
