#app .aps-board-shell .aps-board-loading-caption{
 margin:11px 0 0;
 color:#9fb9de;
 font-size:11px;
 line-height:1.65;
 max-width:540px;
}
#app .aps-board-shell .aps-board-loading-preview{
 position:relative;z-index:1;
 margin-top:22px;
 padding:12px 14px;
 display:grid;
 gap:10px;
 border:1px solid #a5c4ff24;
 border-radius:12px;
 background:linear-gradient(115deg,#f9fdff0b,#7cb2ff07);
