}
#app .aps-board-shell .aps-board-loading-preview-chip-short{width:46px;opacity:.65}
#app .aps-board-shell .aps-board-loading-preview-row{
 display:grid;
 grid-template-columns:1.2fr 1fr .8fr;
 gap:16px;
 align-items:center;
 padding-top:10px;
 border-top:1px solid #d2e1ff1e;
}
#app .aps-board-shell .aps-board-loading-preview-bar{
 display:block;
 width:73%;
 height:9px;
 border-radius:5px;
