#app .aps-board-shell .aps-board-loading-preview-bar-long{width:88%}
#app .aps-board-shell .aps-board-loading-preview-bar-medium{width:61%}
#app .aps-board-shell .aps-board-loading-preview-bar-short{width:42%}
#app .aps-board-shell .aps-board-loading[data-paused="true"] :is(
 .aps-board-loading-halo,.aps-board-loading-orbit,.aps-board-loading-progress-beam){
