}
#app .aps-board-shell .aps-board-loading[data-quality="low"] .aps-board-loading-orbit-inner{
 animation:none;
}
#app .aps-board-shell .aps-board-loading-error{
 display:flex;align-items:flex-start;gap:17px;
 padding:26px;
 border:1px solid #f0c8d0;
 border-radius:15px;
 background:#fff8fa;
}
#app .aps-board-shell .aps-board-loading-error-symbol{
 display:grid;place-items:center;flex:none;
 width:39px;height:39px;border-radius:11px;
 font-size:22px;font-weight:850;
 color:#a43e55;background:#fbe6eb;
}
#app .aps-board-shell .aps-board-loading-error h2{
 font-size:19px;color:#783449;margin:0 0 9px;
