/* FRT New Fund Request: three-step, reference-aligned signed form. */
.frt-wizard-backdrop{background:#11172d99;backdrop-filter:blur(7px)}
.frt-wizard-backdrop .frt-wizard-modal{position:relative;width:min(610px,100%);max-width:610px;height:min(578px,92dvh);max-height:92dvh;border-radius:13px;background:#f8fbfe;border-top:3px solid #49c9ef;padding:0;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 26px 90px #0e1e4059;color:#283346}
.frt-wizard-modal .modal-head{display:flex;flex:0 0 auto;align-items:center;justify-content:space-between;padding:20px 21px 3px 64px;position:relative;margin:0;border:0}
.frt-wizard-modal .modal-head:before{content:'▤';position:absolute;left:21px;top:20px;display:grid;place-items:center;width:35px;height:35px;border-radius:10px;background:linear-gradient(135deg,#4473f8,#0d9cda);box-shadow:0 5px 13px #396def4d;color:white;font-size:21px}
.frt-wizard-modal .modal-head h2{font-size:17px;font-weight:800;color:#202938;letter-spacing:-.025em}
.frt-wizard-modal .modal-close{align-self:flex-start;color:#596275;padding:0 5px;font-size:21px}
.frt-wizard-modal #modal-form{display:flex;flex-direction:column;flex:1;min-height:0;overflow:hidden}
.frt-wizard-intro{padding:0 20px 8px 64px;display:flex;align-items:center;justify-content:space-between;gap:12px}
.frt-wizard-intro p{margin:0;font-size:11px;color:#68788c}
.frt-wizard-status{font-size:10px;font-weight:700;color:#168859;background:#dcf4e7;border-radius:15px;padding:4px 8px;white-space:nowrap}
.frt-wizard-steps{display:flex;align-items:center;flex:0 0 auto;gap:36px;padding:13px 24px 18px;background:#f8fbfe}
