.tl-print-provenance{padding:11px 0;border-bottom:1px solid #dde4ef}
.tl-print-lines table{width:100%;border-collapse:collapse;table-layout:auto;font-size:11px}
.tl-print-lines th{background:#eaf0f9;color:#253955;font-weight:700}
