}
@media print{
 @page{size:A4;margin:15mm 13mm}
 html,body{height:auto!important;overflow:visible!important;margin:0!important;
  background:white!important;color:black!important}
 body>*:not(#tradelink-saved-print){display:none!important}
 #tradelink-saved-print{
  display:block!important;position:static!important;inset:auto!important;
  height:auto!important;max-height:none!important;overflow:visible!important;
  background:white!important;padding:0!important;color:black!important;
  margin:0!important;box-shadow:none!important;
 }
