/* frontend/select-experience.css */
/* APSYNTRA CRM GLOBAL SELECT EXPERIENCE — Vanilla ESM, CSS3, CSS custom properties.
 * Progressive, select-only WAI-ARIA combobox; the original select stays in forms.
 * This does not style or modify three-dot action menus or text search fields. */
:root{
 --aps-select-surface:#fff;
 --aps-select-surface-hover:#f6f8ff;
 --aps-select-ink:#2e456c;
 --aps-select-muted:#7487a5;
 --aps-select-border:#cdd9ef;
 --aps-select-hover-border:#859add;
 --aps-select-focus:#5c72dc;
 --aps-select-highlight:#eef2ff;
 --aps-select-highlight-ink:#3d55b7;
 --aps-select-shadow:0 18px 42px #1a32642c,0 4px 14px #233b6814;
 --aps-select-duration:160ms;
}
select.aps-select-source{
 position:absolute!important;
 width:1px!important;height:1px!important;
 min-width:0!important;min-height:0!important;
 margin:0!important;padding:0!important;border:0!important;
 opacity:0!important;overflow:hidden!important;
 clip-path:inset(50%)!important;
 pointer-events:none!important;
}
.aps-select-anchor{
 position:relative;display:inline-flex;flex-direction:column;
 min-width:0;width:100%;vertical-align:middle;
}
.aps-select-anchor:focus-within{z-index:9999;}
.aps-select-anchor:has(.aps-select-listbox.is-open){z-index:9999;}
.aps-select-trigger{
 box-sizing:border-box;
 display:flex;align-items:center;justify-content:space-between;
 gap:10px;position:relative;min-width:0;width:100%;
 min-height:41px;padding:10px 13px;
 background:var(--aps-select-surface);
 border:1px solid var(--aps-select-border);
 border-radius:10px;
 color:var(--aps-select-ink);
 font:650 12px/1.5 Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
 font-variant-numeric:tabular-nums;
 text-align:left;cursor:pointer;user-select:none;
 box-shadow:inset 0 1px #fff,0 2px 7px #1c32560c;
 transition:background-color var(--aps-select-duration) ease,
  border-color var(--aps-select-duration) ease,
  box-shadow var(--aps-select-duration) ease;
}
.aps-select-trigger:hover:not([aria-disabled="true"]){
 border-color:var(--aps-select-hover-border);
 background:var(--aps-select-surface-hover);
}
.aps-select-trigger:focus-visible{
 outline:3px solid #8194eb9c;outline-offset:2px;
 border-color:var(--aps-select-focus);
 box-shadow:0 0 0 4px #7588ec22;
}
.aps-select-trigger[aria-expanded="true"]{
 background:#fff;border-color:var(--aps-select-focus);
 box-shadow:0 0 0 3px #7588ec1b;
}
.aps-select-trigger[aria-invalid="true"]{
 border-color:#c7485c;box-shadow:0 0 0 3px #c7485c1c;
}
.aps-select-trigger[aria-disabled="true"]{
 background:#f1f3f9;color:#91a0b8;border-color:#dbe2ee;
 cursor:not-allowed;opacity:.78;
}
.aps-select-trigger[data-placeholder="true"] .aps-select-caption{
 color:var(--aps-select-muted);
}
.aps-select-caption{
 display:block;min-width:0;flex:1;
 overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.aps-select-chevron{
 box-sizing:border-box;display:block;flex:none;
 width:9px;height:9px;margin-right:3px;
 border-right:1.7px solid #6477aa;
 border-bottom:1.7px solid #6477aa;
 transform:translateY(-2px) rotate(45deg);
 transition:transform var(--aps-select-duration) ease;
}
.aps-select-trigger[aria-expanded="true"] .aps-select-chevron{
 transform:translateY(2px) rotate(225deg);
}
.aps-select-listbox{
 box-sizing:border-box;
 position:absolute;top:calc(100% + 7px);left:0;visibility:hidden;
 z-index:10000;
 width:100%;min-width:min(170px,calc(100vw - 18px));
 max-width:min(480px,calc(100vw - 18px));min-height:0;
 max-height:min(360px,calc(100dvh - 18px));
 padding:6px;overflow-y:auto;overflow-x:hidden;
 overscroll-behavior:contain;
 background:var(--aps-select-surface);
 border:1px solid #cad7ef;border-radius:13px;
 box-shadow:var(--aps-select-shadow);
 color:var(--aps-select-ink);
 font:600 12px/1.45 Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
 scrollbar-width:thin;scrollbar-color:#a5b5d8 transparent;
}
.aps-select-listbox.is-open{visibility:visible;}
.aps-select-listbox.aps-select-above{top:auto;bottom:calc(100% + 7px);}
.aps-select-listbox.aps-select-end{left:auto;right:0;}
.aps-select-listbox.aps-select-compact{max-height:120px;}
.aps-select-listbox.aps-select-medium{max-height:220px;}
.aps-select-group{
 padding:12px 12px 7px;
 color:var(--aps-select-muted);
 font-size:10px;font-weight:800;letter-spacing:.1em;
 text-transform:uppercase;overflow-wrap:anywhere;
}
.aps-select-option{
 box-sizing:border-box;display:flex;align-items:center;min-width:0;
 min-height:37px;padding:9px 12px;gap:9px;
 border:1px solid transparent;border-radius:8px;
 background:transparent;color:#34496e;
 font-size:12px;font-weight:630;line-height:1.5;
 cursor:pointer;overflow-wrap:anywhere;
}
.aps-select-option[aria-selected="true"],
.aps-select-option.is-active{
 border-color:#c5d1fa;
 background:var(--aps-select-highlight);
 color:var(--aps-select-highlight-ink);
}
.aps-select-option[aria-selected="true"]::after{
 content:"✓";display:block;margin-left:auto;
 font-size:12px;font-weight:900;color:#596bd5;
}
.aps-select-option[aria-disabled="true"]{
 opacity:.45;cursor:not-allowed;
}
.aps-select-option[aria-disabled="true"].is-active{
 background:transparent;border-color:transparent;
}
.aps-select-option:not([aria-disabled="true"]):active{
 background:#e3eaff;
}
@media(max-width:720px){
 .aps-select-trigger{min-height:44px;padding:11px 13px;border-radius:11px;}
