}
#app .aps-sync[data-sync-state="offline"] .aps-sync-orbit,
#app .aps-sync[data-sync-state="error"] .aps-sync-orbit{
 background:conic-gradient(#c45e70 0 180deg,transparent 180deg);
 animation:none;
}
@keyframes aps-sync-orbit{to{transform:rotate(360deg)}}
