}

/* frontend/foreground-overlay.css */
/* CP-CRM-OVERLAY-02 — reliable implicit popover anchoring.
 * showPopover({source:trigger}) supplies the implicit anchor. With anchor()
 * offsets, position-anchor:auto MUST be explicit (not a named anchor).
 * Works for overview-card menus outside .aps-board-shell as well as table cells.
 * Top-layer paint escapes clipped scroll/table ancestors; no z-index inflation.
 */
@supports (position-anchor:auto) and (top:anchor(bottom)){
 .aps-foreground-surface[popover]:popover-open{
  box-sizing:border-box;
  position:fixed!important;
  position-anchor:auto!important;
  inset:auto!important;
  margin:0!important;
  max-height:calc(100dvh - 18px);
  max-width:calc(100vw - 18px);
  overflow-y:auto;
  overscroll-behavior:contain;
  position-try-fallbacks:flip-block,flip-inline;
 }
 /* Keep an unresolved anchor from ever flashing at 0,0. The component
    removes this flag after its first verified layout measurement. */
 .aps-foreground-surface.aps-foreground-pending:popover-open{
  visibility:hidden!important;
 }
 .aps-select-listbox.aps-foreground-select:popover-open{
  top:calc(anchor(bottom) + 7px)!important;
  left:anchor(left)!important;
  right:auto!important;bottom:auto!important;
  width:anchor-size(width);min-width:140px;
  max-width:min(480px,calc(100vw - 18px));
  max-height:min(360px,calc(100dvh - 18px));
 }
 .aps-select-listbox.aps-foreground-select.aps-select-above:popover-open{
  top:auto!important;bottom:calc(anchor(top) + 7px)!important;
 }
 .aps-select-listbox.aps-foreground-select.aps-select-end:popover-open{
  left:auto!important;right:anchor(right)!important;
 }
 /* Unscoped coverage is necessary: Overview board cards are not members
    of the .aps-board-shell subtree. */
 .aps-action-popover.aps-foreground-action:popover-open{
  top:calc(anchor(bottom) + 8px)!important;
  right:anchor(right)!important;
  left:auto!important;bottom:auto!important;
  width:max-content;min-width:210px;
  max-width:min(310px,calc(100vw - 20px));
  max-height:min(370px,calc(100dvh - 20px));
 }
 .aps-action-popover.aps-foreground-action.aps-menu-above:popover-open{
  top:auto!important;bottom:calc(anchor(top) + 8px)!important;
 }
 .aps-action-popover.aps-foreground-action.aps-menu-align-start:popover-open{
  right:auto!important;left:anchor(left)!important;
 }
 .aps-search-suggestions.aps-foreground-search:popover-open{
  top:calc(anchor(bottom) + 8px)!important;
  left:anchor(left)!important;
  right:auto!important;bottom:auto!important;
  width:anchor-size(width);min-width:210px;
  max-width:min(420px,calc(100vw - 18px));
  max-height:min(315px,calc(100dvh - 18px));
 }
 .aps-search-suggestions.aps-foreground-search.aps-search-above:popover-open{
  top:auto!important;bottom:calc(anchor(top) + 8px)!important;
 }
 .aps-search-suggestions.aps-foreground-search.aps-search-align-end:popover-open{
  left:auto!important;right:anchor(right)!important;
 }
}
@media(prefers-reduced-motion:reduce){
 .aps-foreground-surface[popover]:popover-open{
  animation:none!important;transition:none!important;
 }
}

