  color-scheme:light;
  --sm-bg:#F7F8FA;
  --sm-surface:#FFFFFF;
  --sm-surface-soft:#F1F3F7;
  --sm-surface-raised:#FAFBFD;
  --sm-ink:#253047;
  --sm-text:#405068;
  --sm-sub:#626C7D;
  --sm-muted:#647083; /* >=4.5:1 on neutral surfaces */
  --sm-accent:#6667AB;
  --sm-accent-hover:#51528D;
  --sm-accent-soft:#EEEEF8;
  --sm-border:#E3E7ED;
  --sm-border-strong:#CFD6E1;
  --sm-success:#26745D;
  --sm-warning:#946527;
  --sm-danger:#B34755;
  --sm-success-soft:#E9F5F0;
  --sm-warning-soft:#FCF4E6;
  --sm-danger-soft:#FBEFF1;
  --sm-radius-xs:8px;
  --sm-radius-control:11px;
  --sm-radius-card:16px;
  --sm-radius-panel:20px;
  --sm-radius-pill:999px;
  --sm-space-1:4px;
  --sm-space-2:8px;
  --sm-space-3:12px;
  --sm-space-4:16px;
  --sm-space-5:20px;
  --sm-space-6:24px;
  --sm-space-8:32px;
  --sm-space-10:40px;
  --sm-space-12:48px;
  --sm-shadow-sm:0 1px 3px rgba(29,43,68,.035);
  --sm-shadow-card:0 4px 22px rgba(29,43,68,.045);
  --sm-shadow-popover:0 14px 36px rgba(29,43,68,.12);
  --sm-focus:0 0 0 3px rgba(102,103,171,.21);
  --sm-fast:140ms ease-out;
  --sm-normal:180ms ease-out;
  /* Compatibility aliases used by the original base stylesheet. */
  --purple:var(--sm-accent);
  --purple-soft:var(--sm-accent-soft);
  --ink:var(--sm-ink);
  --sub:var(--sm-sub);
  --line:var(--sm-border);
  --canvas:var(--sm-bg);
  --card:var(--sm-surface);
  --green:var(--sm-success);
  --red:var(--sm-danger);
  --shadow:var(--sm-shadow-card);
}
body{background:var(--sm-bg);color:var(--sm-ink)}
#app{color:var(--sm-ink)}
#app :is(button,a,input,select,textarea,summary,[tabindex]):focus-visible{
  outline:2px solid var(--sm-accent);
  outline-offset:3px;
}
#app :is(.primary,.secondary){
  border-radius:var(--sm-radius-control);
  transition:background-color var(--sm-fast),border-color var(--sm-fast),color var(--sm-fast),box-shadow var(--sm-fast);
}
#app .primary{color:#fff;background:var(--sm-accent);border-color:var(--sm-accent);box-shadow:none}
#app .primary:hover:not(:disabled){background:var(--sm-accent-hover);border-color:var(--sm-accent-hover);box-shadow:var(--sm-shadow-sm)}
#app .secondary{color:var(--sm-text);background:var(--sm-surface);border-color:var(--sm-border)}
#app .secondary:hover:not(:disabled){background:var(--sm-surface-raised);border-color:var(--sm-border-strong)}
#app :is(.panel,.modal){background:var(--sm-surface);border-color:var(--sm-border);box-shadow:var(--sm-shadow-card)}
#app :is(.panel,.modal){border-radius:var(--sm-radius-card)}
#app :is(.field input,.field select,.field textarea,.search-input):focus-visible{box-shadow:var(--sm-focus)}
#app .muted{color:var(--sm-sub)}
#app .status{border-radius:var(--sm-radius-xs);font-weight:700}
#app .status:is(.done,.completed){background:var(--sm-success-soft);color:var(--sm-success)}
#app .status:is(.stuck,.blocked){background:var(--sm-danger-soft);color:var(--sm-danger)}
#app .status:is(.todo,.planned){background:var(--sm-surface-soft);color:var(--sm-sub)}
@media(prefers-reduced-motion:reduce){
  #app :is(.primary,.secondary){transition:none}
}

/* Phase 2 — persistent shell, sidebar, workspace selection and topbar. */
#app .shell{min-width:0;background:var(--sm-bg)}
#app :is(.aps-overview-shell,.aps-boards-shell,.aps-board-shell,.aps-settings-shell){
  background:var(--sm-bg);
  color:var(--sm-ink);
}
#app .aps-sidebar{
  --side-ink:var(--sm-ink);
  --side-muted:var(--sm-sub);
  --side-accent:var(--sm-accent);
  --side-line:var(--sm-border);
  --side-surface:var(--sm-surface-raised);
  background:var(--sm-surface-raised);
  border-right:1px solid var(--sm-border);
  box-shadow:none;
}
#app .aps-sidebar .sidebar-brand-wrap{padding-block:24px 18px;border-color:var(--sm-border)}
#app .aps-sidebar .brand{color:var(--sm-ink);font-weight:750}
#app .aps-sidebar .brand:hover{color:var(--sm-accent)}
#app .aps-sidebar .brand-mark{box-shadow:var(--sm-shadow-sm);border-radius:11px}
#app .aps-sidebar .brand-text .csp-u043{color:var(--sm-accent)}
#app .aps-sidebar .sidebar-brand-subtitle{color:var(--sm-sub);letter-spacing:1.05px}
#app .aps-sidebar .workspace-switcher{
  border:1px solid var(--sm-border);
  background:var(--sm-surface);
  border-radius:var(--sm-radius-card);
  box-shadow:var(--sm-shadow-sm);
}
#app .aps-sidebar .workspace-switcher::after{background:none}
#app .aps-sidebar .workspace-icon{
  background:var(--sm-accent-soft);
  color:var(--sm-accent);
  box-shadow:none;
}
#app .aps-sidebar .workspace-name{color:var(--sm-ink);font-weight:740}
#app .aps-sidebar .workspace-sub{color:var(--sm-sub)}
#app .aps-sidebar .side-section{color:var(--sm-sub);letter-spacing:1.1px}
#app .aps-sidebar .nav-link{
  color:var(--sm-sub);
  border-color:transparent;
  border-radius:var(--sm-radius-control);
  font-weight:620;
  transition:background-color var(--sm-fast),color var(--sm-fast),border-color var(--sm-fast);
}
#app .aps-sidebar .nav-link:hover{color:var(--sm-ink);border-color:var(--sm-border);background:var(--sm-surface-soft);transform:none}
#app .aps-sidebar .nav-link.active,
#app .aps-sidebar .nav-link.active:hover{
  color:var(--sm-accent-hover);
  border-color:#dcddec;
  background:var(--sm-accent-soft);
  box-shadow:none;
  transform:none;
  font-weight:740;
}
#app .aps-sidebar .nav-link::before{background:var(--sm-accent)}
#app .aps-sidebar .nav-ico{
  color:var(--sm-muted);
  background:transparent;
  transition:color var(--sm-fast),background-color var(--sm-fast)
}
#app .aps-sidebar .nav-link:hover .nav-ico{color:var(--sm-ink);background:transparent;transform:none}
#app .aps-sidebar .nav-link.active .nav-ico{color:var(--sm-accent);background:transparent}
#app .aps-sidebar .nav-count{color:var(--sm-sub);background:var(--sm-surface-soft)}
#app .aps-sidebar .nav-link.active .nav-count{background:var(--sm-surface);color:var(--sm-accent-hover)}
#app .aps-sidebar .sidebar-nav-section:not(:first-child){border-color:var(--sm-border)}
#app .aps-sidebar .side-bottom{border-color:var(--sm-border)}
#app :is(.aps-overview-shell,.aps-boards-shell,.aps-board-shell,.aps-settings-shell)>.topbar,
#app .topbar{
  background:var(--sm-surface);
  border-bottom:1px solid var(--sm-border);
  box-shadow:none;
}
#app :is(.aps-overview-shell,.aps-boards-shell,.aps-board-shell,.aps-settings-shell) .topbar .breadcrumb,
#app .topbar .breadcrumb{color:var(--sm-sub)}
#app :is(.aps-overview-shell,.aps-boards-shell,.aps-board-shell,.aps-settings-shell) .topbar .breadcrumb strong,
#app .topbar .breadcrumb strong{color:var(--sm-ink);font-weight:700}
#app :is(.aps-overview-shell,.aps-boards-shell,.aps-board-shell,.aps-settings-shell) .topbar .top-pill{
  background:var(--sm-surface-raised);
  color:var(--sm-text);
  border:1px solid var(--sm-border);
  font-weight:650;
  box-shadow:none;
}
#app :is(.aps-overview-shell,.aps-boards-shell,.aps-board-shell,.aps-settings-shell) .topbar .top-avatar{
  color:#fff;
  background:var(--sm-accent);
  box-shadow:none;
  border-radius:var(--sm-radius-control);
  transition:background-color var(--sm-fast);
}
#app :is(.aps-overview-shell,.aps-boards-shell,.aps-board-shell,.aps-settings-shell) .topbar .top-avatar:hover{
  background:var(--sm-accent-hover);
  box-shadow:none;
  transform:none;
}
#app :is(.aps-overview-shell,.aps-boards-shell,.aps-board-shell,.aps-settings-shell)>.main-content{
  box-sizing:border-box;
  width:100%;
  max-width:none;
  padding:clamp(20px,2.5vw,36px) clamp(18px,3vw,48px) 86px;
}
@media(max-width:600px){
  #app :is(.aps-overview-shell,.aps-boards-shell,.aps-board-shell,.aps-settings-shell)>.main-content{
    padding:20px 15px 65px;
  }
}

/* Phase 3 — Overview and My Boards. A single quiet hero treatment replaces
   the former large saturated banners; operational data remains unchanged. */
#app .aps-overview{
  --ov-ink:var(--sm-ink);--ov-sub:var(--sm-sub);
  --ov-line:var(--sm-border);--ov-violet:var(--sm-accent);
}
#app .aps-boards{
  --boards-ink:var(--sm-ink);--boards-sub:var(--sm-sub);
  --boards-border:var(--sm-border);--boards-violet:var(--sm-accent);
}
#app .aps-overview .overview-hero,
#app .aps-boards .boards-hero{
  min-height:145px;
  border:1px solid var(--sm-border);
  border-radius:var(--sm-radius-panel);
  background:var(--sm-surface);
  box-shadow:var(--sm-shadow-card);
  color:var(--sm-ink);
}
#app .aps-overview .overview-hero::after,
#app .aps-boards .boards-hero::after{content:none}
#app .aps-overview .overview-hero-art,
#app .aps-boards .boards-hero-decor{
  color:var(--sm-accent);
  opacity:.12;
}
#app .aps-overview .overview-hero .label-top,
#app .aps-boards .boards-hero .label-top{
  color:var(--sm-accent-hover);
  letter-spacing:1.25px;
  font-weight:750;
}
#app .aps-overview .overview-hero-dot,
#app .aps-boards .boards-hero-dot{
  background:var(--sm-accent);box-shadow:0 0 0 3px var(--sm-accent-soft);
