  font-size:clamp(24px,2.3vw,34px);
  font-weight:750;
}
#app .aps-board-shell .page-head p{color:var(--sm-sub)}
#app .aps-board-shell .page-head .head-actions > .secondary,
#app .aps-board-shell .page-head .board-actions-menu > summary{
  color:var(--sm-text);
