#app .aps-board-shell .page-head .head-actions > .primary:hover{
  color:#fff;background:var(--sm-accent-hover);
  border-color:var(--sm-accent-hover);
}
#app .aps-board-shell .page-head .head-actions > .secondary:hover,
#app .aps-board-shell .page-head .board-actions-menu > summary:hover{
  color:var(--sm-ink);
  background:var(--sm-surface-soft);
  border-color:var(--sm-border-strong);
}
#app .aps-board-shell .page-head .board-actions-menu > summary::after{color:var(--sm-muted)}
#app .aps-board-shell .page-head :is(button,summary):focus-visible{
