}
#app .aps-board-shell .board-customize-toolbar .search-wrap .search-input:focus{
  border-color:var(--sm-accent);background:#fff;box-shadow:var(--sm-focus);
}
#app .aps-board-shell .board-customize-toolbar > .secondary,
#app .aps-board-shell .board-column-menu > summary{
  color:var(--sm-text);
  background:var(--sm-surface-raised);
  border-color:var(--sm-border);
}
#app .aps-board-shell .board-customize-toolbar > .secondary:hover,
#app .aps-board-shell .board-column-menu > summary:hover{
  color:var(--sm-ink);background:var(--sm-surface-soft);
  border-color:var(--sm-border-strong);
}
#app .aps-board-shell .group-heading{margin-top:24px;gap:10px}
#app .aps-board-shell .group-heading::before{
  width:4px;background:var(--sm-accent);
  border-radius:var(--sm-radius-pill);
}
#app .aps-board-shell .group-heading h3{color:var(--sm-ink);font-weight:740}
#app .aps-board-shell .group-heading small{color:var(--sm-sub)}
#app .aps-board-shell .group-heading .board-group-actions > summary{
  color:var(--sm-text);
  background:var(--sm-surface);
  border-color:var(--sm-border);
}
#app .aps-board-shell .panel.board-group-panel{
  background:var(--sm-surface);
  border:1px solid var(--sm-border);
  border-radius:var(--sm-radius-card);
  box-shadow:var(--sm-shadow-sm);
}
#app .aps-board-shell .board-group-scroll{
  scrollbar-color:var(--sm-border-strong) transparent;
}
#app .aps-board-shell .board-group-scroll::-webkit-scrollbar-thumb{
  background:var(--sm-border-strong);
}
#app .aps-board-shell .board-table-custom thead th,
#app .aps-board-shell .board-table-custom thead th.board-frozen-column{
  color:var(--sm-sub);
  background:var(--sm-surface-raised);
  border-color:var(--sm-border);
