/* frontend/board-people.css */
/* BS06 — compact signed board membership avatar tray. */
.board-history-modal:has(.bs02-people){width:min(100%,560px);max-height:min(88dvh,760px);overflow-y:auto}
.bs02-people{margin:12px 0}
.bs02-people-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}
.bs02-people-heading h3{font-size:15px;margin:0 0 3px;font-weight:730}
.bs02-people-subtitle{font-size:12px;color:#7f889f;margin:0}
.bs02-people-count{border-radius:18px;background:#eeedff;color:#5c54a7;font-size:12px;font-weight:750;padding:6px 10px}
.bs02-search-label{display:block;font-size:12px;font-weight:650;margin:15px 0 6px}
#bs02-people-search{display:block;width:100%;box-sizing:border-box;border:1px solid #cfd5e5;border-radius:10px;padding:10px 12px;background:var(--surface,#fff);color:inherit;font:inherit}
.bs02-avatar-grid{display:flex;flex-wrap:wrap;align-items:center;gap:10px 12px;margin:17px 0 13px;padding:6px 0 48px;overflow:visible}
.bs02-avatar-slot{position:relative;display:inline-flex;flex:none}
.bs02-avatar-chip{appearance:none;position:relative;display:inline-grid;place-items:center;border:2px solid transparent;border-radius:50%;background:transparent;cursor:pointer;padding:2px;width:52px;height:52px;overflow:visible}
.bs02-avatar-chip:focus-visible{outline:2px solid #625bd5;outline-offset:3px}
.bs02-person-avatar{position:relative;display:inline-grid;place-items:center;flex:none;border:2px solid #fff;box-shadow:0 0 0 1px #dddff0;width:46px;height:46px;border-radius:50%;background:#eeecff;color:#5e56a7;font-size:13px;font-weight:760;overflow:hidden}
.bs02-person-avatar img[data-avatar-current]{width:100%;height:100%;object-fit:cover;border-radius:50%;position:absolute;inset:0}
.bs02-person-avatar img[data-avatar-current][hidden]{display:none}
.bs02-avatar-tooltip{position:absolute;left:0;top:calc(100% + 7px);z-index:20;transform:translate(0,-4px);background:#27314b;color:#fff;border-radius:9px;padding:8px 11px;min-width:max-content;max-width:min(240px,75vw);box-shadow:0 8px 20px #12203d32;visibility:hidden;opacity:0;pointer-events:none;transition:opacity .12s ease,transform .12s ease;font-size:12px;text-align:center}
.bs02-avatar-tooltip strong{display:block;white-space:normal;overflow-wrap:anywhere}
.bs02-avatar-tooltip small{display:block;font-size:10px;color:#cdd5e6;margin-top:3px}
.bs02-avatar-chip:hover .bs02-avatar-tooltip,.bs02-avatar-chip:focus-visible .bs02-avatar-tooltip{opacity:1;visibility:visible;transform:translate(0,0)}
.bs02-people-empty{font-size:13px;color:#7b8497}
.bs02-people-footnote{font-size:11px;color:#858ca1;line-height:1.55;margin:12px 0 0}
.bs02-people-compact-note{font-size:12px;color:#828ba0;line-height:1.5;margin:2px 0 12px}
.bs02-tools{margin:18px 0 0;border-top:1px solid #e8ebf3;padding-top:13px}
.bs02-tools>summary{font-size:12px;font-weight:680;cursor:pointer;color:#69728a}
.bs02-tools-body{padding:8px 0 3px}
.bs02-tools-body .bs02-mention-draft{margin:12px 0 0;border:0;padding:0}
.bs02-mention-draft>label{display:block;font-weight:650;margin-bottom:8px}
#bs02-mention-editor{display:block;width:100%;box-sizing:border-box;border:1px solid #cfd5e5;border-radius:10px;padding:12px;background:var(--surface,#fff);color:inherit;font:inherit;resize:vertical;min-height:80px}
[data-bs02-mention-options]{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}
[data-bs02-mention-options] button{border:1px solid #c9c7e9;border-radius:24px;background:#f1efff;color:#514a9b;cursor:pointer;padding:7px 12px}
[data-bs02-mention-options] small{font-weight:400;opacity:.8}
.bs02-mention-draft [data-bs02-copy-draft]{margin-top:8px}
@media(prefers-reduced-motion:reduce){.bs02-avatar-tooltip{transition:none}}
@media(max-width:600px){.bs02-avatar-grid{gap:8px}.bs02-avatar-tooltip{min-width:130px;max-width:170px}}

/* frontend/board-share-clean.css */
/* BS04 — clean, compact board Share & Access (presentation only). */
.board-share-stage-overlay{position:fixed;inset:0;z-index:5000;background:#18223c9e;display:grid;place-items:center;padding:18px}
.board-share-stage-frame{width:min(100%,490px);max-height:min(88dvh,760px);overflow-y:auto;border-radius:18px;background:#fff;color:#25314d;box-shadow:0 22px 64px #0c163548}
.board-share-stage{padding:24px 25px 22px}
.board-share-stage-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:19px}
.board-share-stage-title h2{font-size:20px;line-height:1.3;letter-spacing:-.035em;margin:0 0 5px}
.board-share-stage-board{font-size:13px;color:#78829a;margin:0;overflow-wrap:anywhere}
.board-share-stage-close{display:grid;place-items:center;flex:none;width:34px;height:34px;border:1px solid #e1e5ef;border-radius:9px;background:#f9faff;color:#647089;cursor:pointer;font-size:21px;line-height:1}
.board-share-stage-section{padding:17px 0;border-top:1px solid #e7ebf3}
.board-share-stage-row{display:flex;align-items:center;gap:12px;min-width:0}
.board-share-stage-icon{display:grid;place-items:center;flex:none;width:37px;height:37px;background:#f0efff;color:#645dae;border-radius:11px;font-size:19px}
.board-share-stage-copy{flex:1;min-width:0}
.board-share-stage-copy strong{font-size:14px;font-weight:720}
.board-share-stage-copy p{margin:4px 0 0;color:#758098;font-size:12px;line-height:1.5}
.board-share-stage-pill{flex:none;max-width:130px;text-align:center;border-radius:20px;padding:7px 10px;color:#685b9c;background:#f0edff;font-size:11px;font-weight:720}
.board-share-stage button{font-family:inherit}
.board-share-stage-secondary{flex:none;background:#fff;color:#5750a0;border:1px solid #d6d9eb;padding:9px 12px;border-radius:9px;font-weight:650;cursor:pointer;font-size:12px}
.board-share-stage-primary{width:100%;margin-top:15px;background:#6961b2;border:1px solid #6961b2;color:#fff;padding:12px 14px;border-radius:9px;font-size:13px;font-weight:720}
