.bs09-access-result>button{grid-column:2;grid-row:1 / 3;border:1px solid #dfe2eb;border-radius:8px;padding:7px 9px;background:#f5f6fa;color:#959eae;font-size:11px;cursor:not-allowed}
.bs09-access-note{font-size:10px;color:#858fa4;line-height:1.5;margin:0}
.bs09-workspace-invite{display:block;margin:12px 0 1px;max-width:100%}
.bs09-group-create{border:1px solid #d6dbec;border-radius:9px;padding:9px 12px;background:#f7f8fb;color:#929bad;font:inherit;font-size:11px;font-weight:650;text-align:center;cursor:not-allowed}

/* frontend/board-activity-avatars.css */
/* BS07 — compact read-only activity actor avatars. No new data reads. */
.board-history-list .board-activity-event{
 display:grid;grid-template-columns:38px minmax(0,1fr);align-items:start;
 column-gap:11px;padding:13px 6px;min-width:0
}
.board-activity-event-body{min-width:0;display:grid;gap:4px}
.board-activity-event-body .board-history-entry-head{
 display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;
 gap:6px 12px;min-width:0
}
.board-activity-event-body .board-history-entry-head strong{overflow-wrap:anywhere}
.board-activity-event-body .board-history-entry-head time{
 color:#78849a;font-size:11px;white-space:nowrap
}
.board-activity-event-body p{margin:0;line-height:1.45;overflow-wrap:anywhere}
.board-activity-event-body>small{
 color:#8390a5;display:block;font-size:11px;overflow-wrap:anywhere
}
.board-activity-actor-avatar{
 display:inline-grid;place-items:center;position:relative;flex:none;
 width:36px;height:36px;box-sizing:border-box;border-radius:50%;
 background:#eeecff;color:#5751a2;border:1px solid #e0dff4;
 font-weight:760;font-size:11px;line-height:1;overflow:hidden
}
.board-activity-actor-avatar img[data-avatar-current]{
 position:absolute;inset:0;width:100%;height:100%;object-fit:cover;border-radius:50%
}
.board-activity-actor-avatar img[data-avatar-current][hidden]{display:none}
@media(max-width:540px){
 .board-history-list .board-activity-event{grid-template-columns:34px minmax(0,1fr);column-gap:9px}
 .board-activity-actor-avatar{width:32px;height:32px;font-size:10px}
 .board-activity-event-body .board-history-entry-head time{white-space:normal}
}
